M['EOC_BIOKINETIC_AWAKENING_KNACK_HANDLING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_BIOKINETIC_AWAKENING_KNACK_HANDLING'](you, npc, ctx) then
    return false
  end
  if (m.spell_level(you, 'biokin_flexibility_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'biokin_flexibility_knack')
    U.set_spell_level(you, 'biokin_flexibility', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'biokin_flexibility_knack', -(1))
  end
  if (m.spell_level(you, 'biokin_adrenaline_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'biokin_adrenaline_knack')
    U.set_spell_level(you, 'biokin_adrenaline', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'biokin_adrenaline_knack', -(1))
  end
  if (U.spell_count(you, nil) == 0) then
    U.unset_mutation(you, 'PSYCHIC_KNACK')
  end
  return true
end
