  U.add_effect(you, 'effect_biokin_physical', TimeDuration.from_minutes(5), nil, nil)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  util.queue_eoc(function(y) M['EOC_BIOKIN_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
