  util.queue_eoc(function(y) M['EOC_BIOKIN_VITAMINOSIS_ONGOING_NETHER_ATTUNEMENT'](y, npc, ctx) end, you, U.rng((120 + (m.spell_level(you, 'biokin_vitaminosis') * 2)), (300 + (m.spell_level(you, 'biokin_vitaminosis') * 5))))
  util.queue_eoc(function(y) M['EOC_BIOKIN_VITAMINOSIS_EXPERIENCE'](y, npc, ctx) end, you, U.rng((900 - (m.spell_level(you, 'biokin_vitaminosis') * 12)), (1800 - (m.spell_level(you, 'biokin_vitaminosis') * 25))))
