  ctx['portal_storm_center'] = you:get_pos_ms()
  U.save_location(nil, 'portal_storm_center', ctx['portal_storm_center'])
  V.gset('cause_early_portal_storm', 1)
  -- external EOC next_weather (base-game; Phase 4/5)
  -- external EOC EOC_CAUSE_PORTAL_STORM (base-game; Phase 4/5)
  U.unported('EOC_CAUSE_EARLY_PORTAL_STORM_ACTUAL', 'assign_mission')
  U.msg(you, 'You suddenly register a buzzing in your senses.  It\'s getting louder, and your head starts to throb.  Somewhere nearby, a tiny cataclysm has begun (check mission log for details).', MsgType.bad, ctx)
  return true
