M['EOC_CLAIRSENTIENT_AWAKENING_KNACK_HANDLING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_CLAIRSENTIENT_AWAKENING_KNACK_HANDLING'](you, npc, ctx) then
    return false
  end
  if (m.spell_level(you, 'clair_better_senses_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'clair_better_senses_knack')
    U.set_spell_level(you, 'clair_better_senses', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'clair_better_senses_knack', -(1))
  end
  if (m.spell_level(you, 'clair_danger_sense_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'clair_danger_sense_knack')
    U.set_spell_level(you, 'clair_danger_sense', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'clair_danger_sense_knack', -(1))
  end
  if (m.spell_level(you, 'clair_astral_projection_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'clair_astral_projection_knack')
    U.set_spell_level(you, 'clair_astral_projection', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'clair_astral_projection_knack', -(1))
  end
  if (U.spell_count(you, nil) == 0) then
    U.unset_mutation(you, 'PSYCHIC_KNACK')
  end
  return true
end
