M['EOC_CLAIR_ASTRAL_PROJECTION_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_CLAIR_ASTRAL_PROJECTION_INITIATE'](you, npc, ctx) then
    U.add_effect(you, 'effect_no_nether_attunement_from_channel', TimeDuration.from_turns(0), nil, nil)
    U.msg(you, 'Trying to send your spirit out of your body while driving is dangerous at best and suicidal at worst.  You had better not do it.', MsgType.mixed, ctx)
    return false
  end
  M['EOC_CLAIR_ASTRAL_PROJECTION_INITIATE_POST_VEHICLE_CHECK'](you, npc, ctx)
  return true
end
C['EOC_CLAIR_ASTRAL_PROJECTION_INITIATE_POST_VEHICLE_CHECK'] = function(you, npc, ctx)
  ctx = ctx or {}
  return true
end
M['EOC_CLAIR_ASTRAL_PROJECTION_INITIATE_POST_VEHICLE_CHECK'] = function(you, npc, ctx)
  ctx = ctx or {}
  ctx['clair_astral_projection_original_location'] = you:get_pos_ms()
  U.save_location(you, 'clair_astral_projection_original_location', ctx['clair_astral_projection_original_location'])
  U.add_effect(you, 'effect_clair_astral_projection', 'PERMANENT', nil, nil)
  U.add_effect(you, 'incorporeal', 'PERMANENT', nil, nil)
  U.msg(you, 'As you meditate, you feel your spirit slipping free from your body.', MsgType.good, ctx)
  U.set_mutation(you, 'CLAIR_ASTRAL_PROJECTION_APPEARANCE')
  you:create_item(ItypeId.new('body_astral_projection'), U.round(1))
  you:create_item(ItypeId.new('item_clair_astral_projection_cord'), U.round(1))
  U.set_spell_level(you, 'clair_astral_projection_return', 0)
  return true
end
