end
M['EOC_CLAIR_BETTER_SENSES_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_CLAIR_BETTER_SENSES_DRAIN'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'latest_channeled_power_difficulty', 1)
  M['EOC_PSIONICS_GAIN_NETHER_ATTUNEMENT_2'](you, npc, ctx)
  M['EOC_PSI_MAINTENANCE_CALORIE_COST_CALCULATOR'](you, npc, ctx)
  if (m.spell_level(you, 'clair_better_senses') >= 1) then
    m.gain_spell_exp(you, 'clair_better_senses', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  else
    m.gain_spell_exp(you, 'clair_better_senses_knack', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  end
  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_CLAIR_BETTER_SENSES_DRAIN'](y, npc, ctx) end, you, U.rng(((((m.spell_level(you, 'clair_better_senses') + m.spell_level(you, 'clair_better_senses_knack')) * 215) + 595) * J.psionic_power_modifiers(you, npc, ctx)), ((((m.spell_level(you, 'clair_better_senses') + m.spell_level(you, 'clair_better_senses_knack')) * 482) + 1264) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
C['EOC_CLAIR_BETTER_SENSES_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (not you:has_effect(U.eid('effect_clair_better_senses')))
end
M['EOC_CLAIR_BETTER_SENSES_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_CLAIR_BETTER_SENSES_INITIATE'](you, npc, ctx) then
    M['EOC_CLAIR_REMOVE_BETTER_SENSES'](you, npc, ctx)
    return false
  end
  M['EOC_POWER_MAINTENANCE_PLUS_ONE'](you, npc, ctx)
  U.msg(you, 'All of your senses are enhanced.', MsgType.good, ctx)
  U.add_effect(you, 'effect_clair_better_senses', 'PERMANENT', nil, nil)
  util.queue_eoc(function(y) M['EOC_CLAIR_BETTER_SENSES_DRAIN'](y, npc, ctx) end, you, U.rng(((((m.spell_level(you, 'clair_better_senses') + m.spell_level(you, 'clair_better_senses_knack')) * 215) + 595) * J.psionic_power_modifiers(you, npc, ctx)), ((((m.spell_level(you, 'clair_better_senses') + m.spell_level(you, 'clair_better_senses_knack')) * 482) + 1264) * J.psionic_power_modifiers(you, npc, ctx))))
