M['EOC_CLAIR_EXAMINE_ITEM_DETECTION'] = function(you, npc, ctx)
  ctx = ctx or {}
  ctx['artifact_resonance'] = U.unported_num('EOC_CLAIR_EXAMINE_ITEM_DETECTION', 'n_artifact_resonance')
  ctx['resonance_modifier'] = math.min((m.spell_level(you, 'clair_examine_item') + m.spell_level(you, 'clair_examine_item_knack')), 10)
  ctx['resonance_modifier'] = ((10 - (ctx['resonance_modifier'] or 0)) / 50)
  ctx['artifact_resonance'] = ((ctx['artifact_resonance'] or 0) * U.rng((1 - (ctx['resonance_modifier'] or 0)), (1 + (ctx['resonance_modifier'] or 0))))
  if ((ctx['artifact_resonance'] or 0) > 0) then
    U.msg(you, 'The strange object has an otherworldly resonance about it (about <color_light_cyan><context_val:artifact_resonance></color> resonance ).', MsgType.neutral, ctx)
  end
  if U.has_creature_flag(npc, 'FIFTH_SUN_TECHNOLOGY') then
    U.msg(you, 'You have a sense of vast distances from this object, as though it came from a place you would never find on any map.  For a moment, you see an eagle stooping over a snake, wings flashing in the sun, and a vast shape moving through the void between the stars.', MsgType.neutral, ctx)
  end
  return true
end
