  if not C['EOC_CLAIR_LEARNING_EXAMINE_ITEM'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'psi_learning_counter', 0)
  you:learn_recipe(RecipeId.new('practice_clair_examine_item'))
  U.msg(you, 'Use of your powers has led to an insight.  You could examine an item with preternatural senses, discovering information that would be impossible to figure out with any normal investigation, if you can figure out the technique.', MsgType.neutral, ctx)
  return true
end
