    M['EOC_CLAIR_MATRIX_AWAKENING_FAILURE'](you, npc, ctx)
    return false
  end
  M['EOC_CLAIR_MATRIX_AWAKENING_SUCCESS'](you, npc, ctx)
  return true
end
