  ctx = ctx or {}
  return true
end
M['EOC_CLAIR_MATRIX_AWAKENING_FAILURE'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  You see yourself as you could have been, if you had taken that job, if you had sent that text, if you had moved across the country, but only for a moment before your head starts pounding.  You look down at the crystal as its light fades, but the visions do not return.', MsgType.neutral, ctx)
  U.add_effect(you, 'psionic_overload', TimeDuration.from_hours(1), nil, nil)
  U.add_effect(you, 'stunned', TimeDuration.from_turns(10), nil, nil)
  util.queue_eoc(function(y) M['EOC_CLAIR_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  return true
end
C['EOC_CLAIR_MATRIX_AWAKENING_SUCCESS'] = function(you, npc, ctx)
  ctx = ctx or {}
  return true
end
M['EOC_CLAIR_MATRIX_AWAKENING_SUCCESS'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  You remember your childhood, before the end of the world, and then the memories diverge.  You see yourself on an aircraft carrier bridge, looking out the window as a colossal tentacle breaches the surface of the ocean; you stand in a clear white room, watching through a reinforced glass window as your colleague reanimates; you are caught up in the riots and shot by soldiers manning a road block; you are on a camping trip with friends when a nest of pig-sized wasps descend from a formerly-clear sky.  Dozens of lives in quick succession, might-have-beens and never-weres, fragments that fade even as you try to grasp each one in succession.  When the last one ends, you can see through the crystal, through your hands, through the ground.  You can see forever.', MsgType.neutral, ctx)
  M['EOC_PSI_AWAKENING_CLAIRSENTIENCE_FINALIZATION'](you, npc, ctx)
  U.add_effect(you, 'effect_clair_clear_sight', TimeDuration.from_minutes(1), nil, nil)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  util.queue_eoc(function(y) M['EOC_CLAIR_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
  return true
end
