M['EOC_CLAIR_NIGHT_EYES_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_CLAIR_NIGHT_EYES_DRAIN'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'latest_channeled_power_difficulty', 1)
  M['EOC_PSIONICS_GAIN_NETHER_ATTUNEMENT_2'](you, npc, ctx)
  M['EOC_PSI_MAINTENANCE_CALORIE_COST_CALCULATOR'](you, npc, ctx)
  m.gain_spell_exp(you, 'clair_night_vision', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_CLAIR_NIGHT_EYES_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'clair_night_vision') * 150) + 290) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'clair_night_vision') * 270) + 980) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
