M['EOC_CLAIR_NIGHT_EYES_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_CLAIR_NIGHT_EYES_INITIATE'](you, npc, ctx) then
    M['EOC_CLAIR_REMOVE_NIGHT_EYES'](you, npc, ctx)
    return false
  end
  U.msg(you, 'You open your senses to the world.', MsgType.good, ctx)
  M['EOC_POWER_MAINTENANCE_PLUS_ONE'](you, npc, ctx)
  U.add_effect(you, 'effect_clair_night_eyes', 'PERMANENT', nil, nil)
  util.queue_eoc(function(y) M['EOC_CLAIR_NIGHT_EYES_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'clair_night_vision') * 150) + 290) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'clair_night_vision') * 270) + 980) * J.psionic_power_modifiers(you, npc, ctx))))
