  return ((not you:has_trait(U.mid('PROF_CONCENTRATION_INTERMEDIATE'))) and (not U.test_eoc(C, 'EOC_CONDITION_MOM_BANNED_EFFECTS_TO_PRACTICE_CONCENTRATION', you, npc, ctx)) and (m.maintained_count(you) > 0))
end
M['EOC_CONCENTRATION_SUCCESS_PROFICIENCY_INT'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_CONCENTRATION_SUCCESS_PROFICIENCY_INT'](you, npc, ctx) then
    M['EOC_CONCENTRATION_SUCCESS_PROFICIENCY_MASTER'](you, npc, ctx)
    return false
  end
  U.train_proficiency(you, 'PROF_CONCENTRATION_INTERMEDIATE', ((U.rng(0, 4) / 48) * U.game_option('PROFICIENCY_TRAINING_SPEED')))
  return true
end
