    m.gain_spell_exp(you, 'electrokinetic_hacking_interface', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  else
    m.gain_spell_exp(you, 'electrokinetic_hacking_interface_knack', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  end
  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_ELECTROKIN_HACKING_INTERFACE_DRAIN'](y, npc, ctx) end, you, U.rng(((((m.spell_level(you, 'electrokinetic_hacking_interface') + m.spell_level(you, 'electrokinetic_hacking_interface_knack')) * 45) + 600) * J.psionic_power_modifiers(you, npc, ctx)), ((((m.spell_level(you, 'electrokinetic_hacking_interface') + m.spell_level(you, 'electrokinetic_hacking_interface_knack')) * 90) + 1800) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
