    ctx['minimum_duration'] = math.min(((((V.uget(you, 'paralysis_electrokin_power_level') * 0.2) + 1) * V.uget(you, 'paralysis_electrokin_intelligence')) * V.uget(you, 'nether_attunement_paralysis_scaling')), 5)
    ctx['maximum_duration'] = math.min(((((V.uget(you, 'paralysis_electrokin_power_level') * 0.35) + 3) * V.uget(you, 'paralysis_electrokin_intelligence')) * V.uget(you, 'nether_attunement_paralysis_scaling')), 5)
    ctx['duration'] = U.rng((ctx['minimum_duration'] or 0), (ctx['maximum_duration'] or 0))
    U.add_effect(you, 'downed', TimeDuration.from_turns(U.round((ctx['duration'] or 0))), nil, nil)
    U.add_effect(you, 'psi_dazed', TimeDuration.from_turns(U.round((ctx['duration'] or 0))), nil, nil)
    U.add_effect(you, 'effect_electrokin_paralysis', TimeDuration.from_turns(U.round((ctx['duration'] or 0))), nil, nil)
