    if (V.uget(you, 'electrokin_personal_battery_power_count') >= 1) then
      if (V.uget(you, 'electrokin_personal_battery_max_indv_power') >= 1) then
        V.uset(you, 'electrokin_personal_battery_power_count_used', math.min((U.item_power_max(_it) - U.item_power(_it)), V.uget(you, 'electrokin_personal_battery_max_indv_power')))
      else
