  end
  U.run_inv_eocs(you, ctx, 'random', {excluded_flags = {'USES_BIONIC_POWER', 'IS_UPS'}}, function(_it)
    U.item_add_power(_it, -((U.rng(0, 200) + 50)))
  end)
  return true
end
C['EOC_ELECTRONKINETIC_MONSTER_POWER_DRAINING_INV_RESULT'] = function(you, npc, ctx)
  ctx = ctx or {}
  return true
end
