  U.unported('EOC_ELECTRONKINETIC_MONSTER_POWER_DRAINING_INV_RESULT', 'write n_val:power')
  return true
end
C['EOC_ELECTRONKINETIC_MONSTER_POWER_DRAINING_MONSTER_CHECK'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (U.x_in_y(1, 3) and U.has_creature_flag(you, 'ELECTRIC'))
end
M['EOC_ELECTRONKINETIC_MONSTER_POWER_DRAINING_MONSTER_CHECK'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_ELECTRONKINETIC_MONSTER_POWER_DRAINING_MONSTER_CHECK'](you, npc, ctx) then
