end
C['EOC_ELECTRO_CRYSTAL_DRAINING'] = function(you, npc, ctx)
  ctx = ctx or {}
  return U.has_item(you, 'matrix_crystal_electrokinesis')
end
M['EOC_ELECTRO_CRYSTAL_DRAINING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_ELECTRO_CRYSTAL_DRAINING'](you, npc, ctx) then
    return false
  end
  U.unported('EOC_ELECTRO_CRYSTAL_DRAINING', 'u_consume_item')
  you:create_item(ItypeId.new('matrix_crystal_drained'), U.round(1))
  return true
end
C['EOC_ELECTRO_MATRIX_AWAKENING'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (you:has_trait(U.mid('ELECTROKINETIC')) or you:has_trait(U.mid('CANNOT_GAIN_PSIONICS')))
end
M['EOC_ELECTRO_MATRIX_AWAKENING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_ELECTRO_MATRIX_AWAKENING'](you, npc, ctx) then
    V.uset(you, 'awakening_reducer', J.matrix_awakening_odds(you, npc, ctx, V.uget(you, 'awakening_countup')))
    M['EOC_ELECTRO_MATRIX_AWAKENING_2'](you, npc, ctx)
    return false
  end
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  It starts pulsing, first slowly and more rapidly, and your head starts pounding in time with the light.  You tear your gaze away but the pounding in your head remains.', MsgType.neutral, ctx)
  U.add_effect(you, 'psionic_overload', TimeDuration.from_hours(1), nil, nil)
  U.add_effect(you, 'stunned', TimeDuration.from_turns(10), nil, nil)
  return true
end
C['EOC_ELECTRO_MATRIX_AWAKENING_2'] = function(you, npc, ctx)
  ctx = ctx or {}
  return U.test_eoc(C, 'EOC_CONDITION_AWAKENING_X_IN_Y_CHANCE', you, npc, ctx)
end
M['EOC_ELECTRO_MATRIX_AWAKENING_2'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_ELECTRO_MATRIX_AWAKENING_2'](you, npc, ctx) then
    M['EOC_ELECTRO_MATRIX_AWAKENING_FAILURE'](you, npc, ctx)
    return false
  end
  M['EOC_ELECTRO_MATRIX_AWAKENING_SUCCESS'](you, npc, ctx)
  return true
end
C['EOC_ELECTRO_MATRIX_AWAKENING_3'] = function(you, npc, ctx)
  ctx = ctx or {}
  return you:has_trait(U.mid('ELECTROKINETIC'))
end
M['EOC_ELECTRO_MATRIX_AWAKENING_3'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_ELECTRO_MATRIX_AWAKENING_3'](you, npc, ctx) then
    M['EOC_ELECTRO_MATRIX_AWAKENING_SUCCESS'](you, npc, ctx)
    return false
  end
  M['EOC_ELECTRO_MATRIX_AWAKENING_FAILURE'](you, npc, ctx)
  return true
end
C['EOC_ELECTRO_MATRIX_AWAKENING_FAILURE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return true
end
M['EOC_ELECTRO_MATRIX_AWAKENING_FAILURE'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  As it fills your vision, your muscles tremble.  You see bursts of internal lightning traveling down your limbs for a moment, and then your muscles seize up in a sudden shower of internal sparks.  As the crystal\'s light fades you crash to the floor.', MsgType.neutral, ctx)
  U.add_effect(you, 'psionic_overload', TimeDuration.from_hours(1), nil, nil)
  U.add_effect(you, 'stunned', TimeDuration.from_turns(10), nil, nil)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  util.queue_eoc(function(y) M['EOC_ELECTRO_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
  return true
end
C['EOC_ELECTRO_MATRIX_AWAKENING_SUCCESS'] = function(you, npc, ctx)
  ctx = ctx or {}
  return true
end
M['EOC_ELECTRO_MATRIX_AWAKENING_SUCCESS'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  As it fills your vision, you see thin lines beneath your skin.  They pulse with energy, bright sparks traveling to your fingers as you flex them and a burst of internal lightning when you touch the crystal with your free hand.  You raise your hand and hold up two fingers, and a thunderbolt jumps between them accompanied by a loud crackle.  Your hair stands on end as lightning travels down your arm, filling the air with the scent of ozone.  As the light from the crystal fades, leaving it dull and colorless, your skin tingles.', MsgType.neutral, ctx)
  M['EOC_PSI_AWAKENING_ELECTROKINESIS_FINALIZATION'](you, npc, ctx)
  U.add_effect(you, 'effect_electrokin_zap_enemies', TimeDuration.from_minutes(5), nil, nil)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  util.queue_eoc(function(y) M['EOC_ELECTRO_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
  return true
end
