  U.msg(you, 'Your muscles suddenly seize up!', MsgType.bad, ctx)
  U.add_effect(you, 'downed', U.rng_dur(TimeDuration.from_turns(2), TimeDuration.from_turns(8)), nil, nil)
  U.add_effect(you, 'stunned', U.rng_dur(TimeDuration.from_turns(1), TimeDuration.from_turns(4)), nil, nil)
  util.queue_eoc(function(y) M['EOC_ELECTRO_OVERLOAD_ZAP'](y, npc, ctx) end, you, U.rng(60, 2700))
  return true
end
