C['EOC_ENERVATION_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (((ctx['damage_taken'] or 0) > 0) and (not U.has_creature_flag(npc, 'LIFESHIELD')) and (not U.has_creature_flag(npc, 'ENERVATE_IMMUNE')))
end
