  M['EOC_ENERVATION_DRAIN_2'](you, npc, ctx)
  return true
end
C['EOC_ENERVATION_DRAIN_2'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (U.unported_num('EOC_ENERVATION_DRAIN_2', 'n_val:mana') >= 150)
end
M['EOC_ENERVATION_DRAIN_2'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_ENERVATION_DRAIN_2'](you, npc, ctx) then
    M['EOC_ENERVATION_DRAIN_3'](you, npc, ctx)
    return false
  end
  U.unported('EOC_ENERVATION_DRAIN_2', 'write n_val:mana')
  U.msg(npc, 'You feel a sudden sense of loss.', MsgType.bad, ctx)
  return true
end
C['EOC_ENERVATION_DRAIN_3'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (m.stamina(npc) >= 200)
end
M['EOC_ENERVATION_DRAIN_3'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_ENERVATION_DRAIN_3'](you, npc, ctx) then
    U.cast_spell(npc, 'eater_drain_health', nil, nil)
    U.msg(npc, 'You feel your life draining away!', MsgType.bad, ctx)
    return false
  end
  U.unported('EOC_ENERVATION_DRAIN_3', 'write n_val:stamina')
  U.msg(npc, 'For a moment, you feel exhausted.', MsgType.bad, ctx)
  return true
end
