  ctx = ctx or {}
  if not C['EOC_GAMESTART_RANDOMIZE_AWAKENING_ODDS_2'](you, npc, ctx) then
    V.uset(you, 'has_initial_awakening_countup_set', 1)
    return false
  end
  V.uset(you, 'awakening_countup', (V.uget(you, 'awakening_countup')) + (1))
  V.uset(you, 'has_initial_awakening_countup_set', 1)
  return true
end
