    util.queue_eoc(function(y) M['EOC_PORTAL_OUBLIETTE_RETURN'](y, npc, ctx) end, you, (ctx['dimension_time'] or 0))
  elseif _sw >= 5 then
    U.unported('EOC_MOM_OUBLIETTE_MONSTER_PICK_DIMENSION', 'u_travel_to_dimension')
    util.queue_eoc(function(y) M['EOC_PORTAL_HIGHLANDS_RETURN'](y, npc, ctx) end, you, (ctx['dimension_time'] or 0))
  elseif _sw >= 3 then
    U.unported('EOC_MOM_OUBLIETTE_MONSTER_PICK_DIMENSION', 'u_travel_to_dimension')
    util.queue_eoc(function(y) M['EOC_PORTAL_OUBLIETTE_RETURN'](y, npc, ctx) end, you, (ctx['dimension_time'] or 0))
  elseif _sw >= 0 then
    U.unported('EOC_MOM_OUBLIETTE_MONSTER_PICK_DIMENSION', 'u_travel_to_dimension')
    util.queue_eoc(function(y) M['EOC_PORTAL_OUBLIETTE_RETURN'](y, npc, ctx) end, you, (ctx['dimension_time'] or 0))
  end
  return true
end
