M['EOC_NOETIC_RESONANCE_DETECT_PSI_POWER_PART_TWO'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_NOETIC_RESONANCE_DETECT_PSI_POWER_PART_TWO'](you, npc, ctx) then
    U.msg(you, 'The machine requires a test subject to report any results.', MsgType.neutral, ctx)
    return false
  end
  if (you:has_trait(U.mid('BIOKINETIC')) or you:has_trait(U.mid('CLAIRSENTIENT')) or you:has_trait(U.mid('PHOTOKINETIC')) or you:has_trait(U.mid('PYROKINETIC')) or you:has_trait(U.mid('TELEKINETIC')) or you:has_trait(U.mid('TELEPATH')) or you:has_trait(U.mid('TELEPORTER')) or you:has_trait(U.mid('VITAKINETIC'))) then
    ctx['already_psi'] = 1
  else
    ctx['already_psi'] = 0
  end
  if you:has_trait(U.mid('ALWAYS_GAIN_PSIONICS')) then
    U.msg(you, 'The lights inside in the machine blink and swirl for what seems like forever until the machine beeps.  On the output screen, the words "<color_magenta>Potential: Excellent.  Mathematician Target</color>" are visible.', MsgType.neutral, ctx)
    U.add_effect(you, 'psionic_overload', TimeDuration.from_minutes(30), 'head', nil)
  end
  if you:has_trait(U.mid('CANNOT_GAIN_PSIONICS')) then
    ctx['awakening_check'] = -(100)
  else
    ctx['awakening_check'] = (100 - J.matrix_awakening_odds(you, npc, ctx, V.uget(you, 'awakening_countup')))
  end
  if ((ctx['awakening_check'] or 0) == -(100)) then
    U.msg(you, 'The lights inside in the machine blink and swirl for what seems like forever until the machine beeps.  On the output screen, the words "<color_light_red>Potential: Null</color>" are visible.', MsgType.neutral, ctx)
  end
  if (((ctx['awakening_check'] or 0) >= 0) and ((ctx['awakening_check'] or 0) <= 5)) then
    U.msg(you, 'The lights inside in the machine blink and swirl for what seems like forever until the machine beeps.  On the output screen, the words "<color_light_red>Potential: Negligible</color>" are visible.', MsgType.neutral, ctx)
  end
  if (((ctx['awakening_check'] or 0) > 5) and ((ctx['awakening_check'] or 0) <= 15)) then
    U.msg(you, 'The lights inside in the machine blink and swirl for what seems like forever until the machine beeps.  On the output screen, the words "<color_yellow>Potential: Minor</color>" are visible.', MsgType.neutral, ctx)
  end
  if (((ctx['awakening_check'] or 0) > 15) and ((ctx['awakening_check'] or 0) <= 45)) then
    U.msg(you, 'The lights inside in the machine blink and swirl for what seems like forever until the machine beeps.  On the output screen, the words "<color_light_green>Potential: Moderate</color>" are visible.', MsgType.neutral, ctx)
  end
  if (((ctx['awakening_check'] or 0) > 45) and ((ctx['awakening_check'] or 0) <= 99)) then
    U.msg(you, 'The lights inside in the machine blink and swirl for what seems like forever until the machine beeps.  On the output screen, the words "<color_light_blue>Potential: Good</color>" are visible.', MsgType.neutral, ctx)
  end
  if ((ctx['already_psi'] or 0) == 1) then
    U.msg(you, 'Below it in red are the words: <color_light_red>WARNING: Noetic activity detected.', MsgType.neutral, ctx)
    U.add_effect(you, 'psionic_overload', TimeDuration.from_minutes(30), 'head', nil)
  else
    if (not you:has_trait(U.mid('CANNOT_GAIN_PSIONICS'))) then
      U.add_effect(you, 'psionic_overload', TimeDuration.from_minutes(30), 'head', nil)
    end
  end
  return true
end
