  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_PHOTOKIN_LIGHT_ARMY_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'photokinetic_light_army') * 4.5) + 37.4) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'photokinetic_light_army') * 11) + 96.5) * J.psionic_power_modifiers(you, npc, ctx))))
