M['EOC_PHOTOKIN_LIGHT_ARMY_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PHOTOKIN_LIGHT_ARMY_INITIATE'](you, npc, ctx) then
    M['EOC_PHOTOKIN_REMOVE_LIGHT_ARMY'](you, npc, ctx)
    return false
  end
  U.msg(you, 'A myriad of duplicates of yourself appear nearby!', MsgType.good, ctx)
  U.add_effect(you, 'effect_photokin_light_army', 'PERMANENT', nil, nil)
  M['EOC_POWER_MAINTENANCE_PLUS_ONE'](you, npc, ctx)
  M['EOC_POWER_MAINTENANCE_PLUS_ONE'](you, npc, ctx)
