    return false
  end
  V.uset(you, 'psi_learning_counter', 0)
  you:learn_recipe(RecipeId.new('practice_photokinetic_camouflage'))
  U.msg(you, 'Use of your powers has led to an insight.  You could bend the light not only around yourself, but around your nearby surroundings, blending them together and making yourself very difficult to spot from a distance, if you can figure out the proper technique.', MsgType.neutral, ctx)
  return true
end
