C['EOC_PORTAL_BIOKIN_AWAKENING'] = function(you, npc, ctx)
  ctx = ctx or {}
  return ((not you:has_trait(U.mid('BIOKINETIC'))) and (not you:has_effect(U.eid('psionic_awakened'))) and U.test_eoc(C, 'EOC_CONDITION_AWAKENING_X_IN_Y_CHANCE', you, npc, ctx))
end
M['EOC_PORTAL_BIOKIN_AWAKENING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PORTAL_BIOKIN_AWAKENING'](you, npc, ctx) then
    U.msg(you, 'A roar fills your mind, louder even than the screaming madness of the portal storm.  Your head pounds in time with the kaleidoscoping sky as your muscles begin cramping uncontrollably.  They suddenly seize up and you collapse to the ground, staring up at the sky, unable to move.', MsgType.neutral, ctx)
    U.add_effect(you, 'psionic_overload', TimeDuration.from_turns(U.round((V.gget('ps_str') * U.time(' 1 h')))), nil, nil)
    U.add_effect(you, 'effect_biokin_overload', TimeDuration.from_turns(U.round((V.gget('ps_str') * U.time(' 2 h')))), nil, nil)
    U.add_effect(you, 'downed', TimeDuration.from_turns(U.round((V.gget('ps_str') * U.time(' 5 s')))), nil, nil)
    U.add_effect(you, 'motor_seizure', TimeDuration.from_turns(U.round((V.gget('ps_str') * U.time(' 5 s')))), nil, nil)
    you:set_stamina(U.round((m.stamina(you)) - (4000)))
    return false
  end
  U.msg(you, 'A roar fills your mind, louder even than the screaming madness of the portal storm.  New strength and vigor suddenly fill you.  You stand up straight and tall, heedless of the wind and the kaleidoscoping sky, and clench your fists.  You feel like you could take on the world, like you could sprint for an hour without stopping, like you could wrestle one of those giant insects to the ground and pin it, like you could dodge bullets.  You unclench your fists and shake your head, but the sense of strength remains.', MsgType.neutral, ctx)
  M['EOC_PSI_AWAKENING_BIOKINESIS_FINALIZATION'](you, npc, ctx)
  U.add_effect(you, 'psionic_awakened', TimeDuration.from_turns(U.round((V.gget('ps_str') * U.time(' 2 h')))), nil, nil)
  V.uset(you, 'awakening_reducer', J.portal_storm_awakening_odds(you, npc, ctx, V.uget(you, 'awakening_countup')))
  return true
end
C['EOC_PORTAL_BLINK'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (U.is_outside(you) and U.x_in_y(1, 20) and (not U.has_creature_flag(you, 'TELEPORT_LOCK')) and (not U.has_creature_flag(you, 'TELESTOP')) and U.test_eoc(C, 'EOC_PORTAL_STORM_CONDITION_FLAG_PORTAL_PROOF', you, npc, ctx))
end
