  if not C['EOC_PORTAL_BLINK'](you, npc, ctx) then
    return false
  end
  U.cast_spell(you, 'teleport_blink_monster', (V.gget('ps_str') / 2), nil)
  V.uset(you, 'ire', (V.uget(you, 'ire')) - (2))
  U.msg(you, 'The world shifts around you!', MsgType.bad, ctx)
  return true
end
C['EOC_PORTAL_CLAIR_AWAKENING'] = function(you, npc, ctx)
  ctx = ctx or {}
  return ((not you:has_trait(U.mid('CLAIRSENTIENT'))) and (not you:has_effect(U.eid('psionic_awakened'))) and U.test_eoc(C, 'EOC_CONDITION_AWAKENING_X_IN_Y_CHANCE', you, npc, ctx))
end
M['EOC_PORTAL_CLAIR_AWAKENING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PORTAL_CLAIR_AWAKENING'](you, npc, ctx) then
    U.msg(you, 'A roar fills your mind, louder even than the screaming madness of the portal storm.  Your head pounds in time with the kaleidoscoping sky as your vision wavers.  The sky grows bright, and then dark.  Sounds fade away before roaring in your ears, and then the entire world suddenly vanishes, leaving you in silent darkness.', MsgType.neutral, ctx)
    U.add_effect(you, 'psionic_overload', TimeDuration.from_turns(U.round((V.gget('ps_str') * U.time(' 1 h')))), nil, nil)
    U.add_effect(you, 'hallu', TimeDuration.from_turns(U.round((V.gget('ps_str') * U.time(' 3 h')))), nil, nil)
    U.add_effect(you, 'blind_clair_overload', TimeDuration.from_turns(U.round((V.gget('ps_str') * U.time(' 15 s')))), nil, nil)
    U.add_effect(you, 'deaf_clair_overload', TimeDuration.from_turns(U.round((V.gget('ps_str') * U.time(' 15 s')))), nil, nil)
    you:set_stamina(U.round((m.stamina(you)) - (4000)))
    return false
  end
  U.msg(you, 'A roar fills your mind, louder even than the screaming madness of the portal storm.  You close your eyes but you can still see--at first just a light against your eyelids, then like a train approaching the end of a tunnel, light expands and reveals your surroundings.  You can see in all directions.  You can see behind and beneath every blade of grass around you, illuminated in the storm\'s witchlight, for a moment until your awareness snaps back into your body and you reel back with the shock of it.  When you open your eyes again, the colors around you are brighter and the sounds are clearer than before.', MsgType.neutral, ctx)
  M['EOC_PSI_AWAKENING_CLAIRSENTIENCE_FINALIZATION'](you, npc, ctx)
  U.add_effect(you, 'psionic_awakened', TimeDuration.from_turns(U.round((V.gget('ps_str') * U.time(' 2 h')))), nil, nil)
  V.uset(you, 'awakening_reducer', J.portal_storm_awakening_odds(you, npc, ctx, V.uget(you, 'awakening_countup')))
  return true
end
