M['EOC_PORTAL_CONSCIOUSNESS_BLIP'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PORTAL_CONSCIOUSNESS_BLIP'](you, npc, ctx) then
    return false
  end
  ctx['value'] = (math.min((V.gget('ps_str') * 0.1), 5) + 1)
  U.add_effect(you, 'psi_stunned', TimeDuration.from_turns(U.round((ctx['value'] or 0))), nil, nil)
  U.assign_activity(you, 'ACT_GENERIC_EOC', (ctx['value'] or 0))
  V.uset(you, 'ire', (V.uget(you, 'ire')) - (3))
  U.msg(you, 'Your head tingles and the world suddenly lurches!', MsgType.bad, ctx)
  return true
end
