  ctx = ctx or {}
  return (((U.is_weather('distant_portal_storm') and U.x_in_y(5, 10)) or (U.is_weather('near_portal_storm') and U.x_in_y(7, 10)) or U.is_weather('portal_storm')) and (V.gget('portal_dungeon_level') == 0) and (V.uget(you, 'ire') > 0))
