M['EOC_PORTAL_EFFECTS_ACTIVE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PORTAL_EFFECTS_ACTIVE'](you, npc, ctx) then
    return false
  end
  U.unported('EOC_PORTAL_EFFECTS_ACTIVE', 'run unknown EOC_PORTAL_MESSAGE')
  util.weighted_call({{function(y,n,c) M['EOC_PORTAL_TELEPORT_STUCK_START'](y,n,c) end, 2}, {function(y,n,c) M['EOC_PORTAL_PAIN'](y,n,c) end, 2}, {function(y,n,c) M['EOC_PORTAL_DIMENSION_TRAVEL'](y,n,c) end, 1}, {function(y,n,c) M['EOC_PORTAL_HALLUCINATOR'](y,n,c) end, 2}, {function(y,n,c) M['EOC_PORTAL_SMOKE'](y,n,c) end, 2}, {function(y,n,c) M['EOC_PORTAL_YRAX_ATTENTION'](y,n,c) end, 1}, {function(y,n,c) M['EOC_PORTAL_SWARM_STRUCTURE'](y,n,c) end, 2}, {function(y,n,c) M['EOC_PORTAL_TAUNT'](y,n,c) end, 1}, {function(y,n,c) M['EOC_PORTAL_SHIFTING_MASS'](y,n,c) end, 1}, {function(y,n,c) M['EOC_PORTAL_ARTIFACT_WEAK'](y,n,c) end, 1}, {function(y,n,c) M['EOC_PORTAL_CONSCIOUSNESS_BLIP'](y,n,c) end, 1}, {function(y,n,c) M['EOC_PORTAL_BLINK'](y,n,c) end, 2}, {function(y,n,c) M['EOC_PORTAL_TEMPORARY_TEARS_IN_REALITY'](y,n,c) end, 1}}, you, npc, ctx)
  return true
end
