    M['EOC_CONCENTRATION_IN_NETHER_AREAS_ATTUNEMENT'](you, npc, ctx)
    M['EOC_NETHER_ATTUNEMENT_FEEDBACK_CHECK_CONCENTRATION'](you, npc, ctx)
