    M['EOC_CONCENTRATION_CHECK_FOR_NETHER_ATTUNEMENT_BACKLASH'](you, npc, ctx)
    M['EOC_CONCENTRATION_VS_LIMIT_CALCULATIONS'](you, npc, ctx)
    m.gain_skill_exp(you, 'metaphysics', U.round(((75 * V.uget(you, 'latest_channeled_power_difficulty')) * U.game_option('SKILL_TRAINING_SPEED'))))
    return false
  end
  U.msg(you, 'Your concentration breaks!', MsgType.bad, ctx)
  M['EOC_END_PSI_POWERS_MAINTAINED'](you, npc, ctx)
  M['EOC_CONCENTRATION_FAILURE_REDUCE_FOCUS'](you, npc, ctx)
  U.cancel_activity(you)
  U.attunement_set(you, (m.attunement(you)) + (((U.rng(3, 8) * m.maintained_count(you)) / J.concentration_calculations(you, npc, ctx))))
  m.gain_skill_exp(you, 'metaphysics', U.round(((15 * V.uget(you, 'latest_channeled_power_difficulty')) * U.game_option('SKILL_TRAINING_SPEED'))))
  M['EOC_CONCENTRATION_CHECK_FOR_NETHER_ATTUNEMENT_BACKLASH'](you, npc, ctx)
  return true
end
