    return false
  end
  V.usets(you, 'latest_studied_power_name', 'biokin_adrenaline')
  M['EOC_PSI_STUDYING_BIOKIN_POWER_SETUP'](you, npc, ctx)
  if (m.spell_level(you, 'biokin_adrenaline') >= 1) then
