    M['EOC_PSI_PRACTICE_FOCUS_MOD'](you, npc, ctx)
    util.queue_eoc(function(y) M['EOC_PRACTICE_BIOKIN_ADRENALINE_LEARNING'](y, npc, ctx) end, you, U.rng(J.learn_new_power_lower_time_bound(you, npc, ctx, V.uget(you, 'latest_studied_power_difficulty')), J.learn_new_power_upper_time_bound(you, npc, ctx, V.uget(you, 'latest_studied_power_difficulty'))))
