C['EOC_PRACTICE_PSIONICS_FINAL_LEARNING_CHECK'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (J.learn_new_power_learn_roll(you, npc, ctx) >= J.learn_new_power_difficulty_setting(you, npc, ctx))
end
M['EOC_PRACTICE_PSIONICS_FINAL_LEARNING_CHECK'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PRACTICE_PSIONICS_FINAL_LEARNING_CHECK'](you, npc, ctx) then
    U.msg(you, 'You just couldn\'t manage to grasp the technique.  You\'ll have to try again.', MsgType.neutral, ctx)
    U.attunement_set(you, (m.attunement(you)) + (U.rng(J.learn_new_power_lower_nether_attunement_level(you, npc, ctx), J.learn_new_power_upper_nether_attunement_level(you, npc, ctx))))
    you:remove_effect(U.eid('effect_psi_learning_new_power'))
    U.cancel_activity(you)
    return false
  end
  U.msg(you, 'You are studying <spell_name:<u_val:latest_studied_power_name>> whose ID is <u_val:latest_studied_power_name> with Difficulty <u_val:latest_studied_power_difficulty> and requires the <u_val:latest_studied_power_proficiency> proficiency', MsgType.debug, ctx)
  U.msg(you, 'As you meditate, all the pieces suddenly come together.  You\'ve unlocked: <spell_name:<u_val:latest_studied_power_name>>.', MsgType.neutral, ctx)
  U.set_spell_level(you, V.ustr(you, 'latest_studied_power_name'), 1)
  M['EOC_PRACTICE_PSIONICS_FINAL_LEARNING_CHECK_SPECIAL_EXCEPTIONS'](you, npc, ctx)
  U.attunement_set(you, (m.attunement(you)) + (U.rng(J.learn_new_power_lower_nether_attunement_level(you, npc, ctx), J.learn_new_power_upper_nether_attunement_level(you, npc, ctx))))
  you:remove_effect(U.eid('effect_psi_learning_new_power'))
  U.cancel_activity(you)
  return true
end
