M['EOC_PSI_STUDYING_POWER_BEGIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PSI_STUDYING_POWER_BEGIN'](you, npc, ctx) then
    U.msg(you, 'You are too exhausted to contemplate anything.', MsgType.bad, ctx)
    return false
  end
  if (m.maintained_count(you) > 0) then
    if U.badcond('EOC_PSI_STUDYING_POWER_BEGIN', 'u_query') then
      M['EOC_END_PSI_POWERS_MAINTAINED'](you, npc, ctx)
    end
  end
  U.msg(you, 'You spend some time meditating and contemplating your powers.', MsgType.good, ctx)
  V.uset(you, 'psi_studying_tick_experience_counter', 0)
  U.add_effect(you, 'effect_psi_studying_power', TimeDuration.from_hours(24), nil, nil)
  U.assign_activity(you, 'ACT_PSI_STUDYING_POWER', 86400)
  M['EOC_PSI_STUDYING_DUST_CONVERSION'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_PSI_STUDYING_POWER_METAPHYSICS_GAIN'](y, npc, ctx) end, you, U.rng(30, 300))
  return true
end
