M['EOC_PSI_TRANSPORTER_REMOTE_TELEPORT_TRANSPORT'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PSI_TRANSPORTER_REMOTE_TELEPORT_TRANSPORT'](you, npc, ctx) then
    return false
  end
  local _pick = U.select_eoc_menu('', {'EOC_PSI_TRANSPORTER_REMOTE_TELEPORT_TRANSPORT_YES', 'EOC_PSI_TRANSPORTER_REMOTE_TELEPORT_TRANSPORT_NO'}, {'Confirm the Coordinates', 'Turn the remove off'}, {'Activate the remote and transport yourself to your destination.', 'Turn the remote off for now.'}, you, npc, ctx, false)
  if not _pick then return false end
  M[_pick](you, npc, ctx)
  return true
end
