  U.msg(you, 'Instead of confirming the destination, you press the button and turn the transporter remote off.', MsgType.neutral, ctx)
  U.run_inv_eocs(you, ctx, 'random', {ids = {'psionic_transporter_remote_on'}}, function(_it)
