M['EOC_PYROKINETIC_AWAKENING_KNACK_HANDLING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PYROKINETIC_AWAKENING_KNACK_HANDLING'](you, npc, ctx) then
    return false
  end
  if (m.spell_level(you, 'pyrokinetic_eruption_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'pyrokinetic_eruption_knack')
    U.set_spell_level(you, 'pyrokinetic_eruption', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'pyrokinetic_eruption_knack', -(1))
  end
  if (m.spell_level(you, 'pyrokinetic_flash_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'pyrokinetic_flash_knack')
    U.set_spell_level(you, 'pyrokinetic_flash', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'pyrokinetic_flash_knack', -(1))
  end
  if (m.spell_level(you, 'pyrokinetic_call_flames_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'pyrokinetic_call_flames_knack')
    U.set_spell_level(you, 'pyrokinetic_call_flames', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'pyrokinetic_call_flames_knack', -(1))
  end
  if (m.spell_level(you, 'pyrokinetic_cloak_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'pyrokinetic_cloak_knack')
    U.set_spell_level(you, 'pyrokinetic_cloak', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'pyrokinetic_cloak_knack', -(1))
  end
  if (U.spell_count(you, nil) == 0) then
    U.unset_mutation(you, 'PSYCHIC_KNACK')
  end
  return true
end
