M['EOC_PYROKIN_BLAZING_AURA_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PYROKIN_BLAZING_AURA_DRAIN'](you, npc, ctx) then
    return false
  end
  if (m.spell_level(you, 'pyrokinetic_aura') >= 1) then
    V.uset(you, 'latest_channeled_power_difficulty', U.spell_difficulty('pyrokinetic_aura'))
  else
    V.uset(you, 'latest_channeled_power_difficulty', U.spell_difficulty('pyrokinetic_aura_knack'))
  end
  M['EOC_PSIONICS_GAIN_NETHER_ATTUNEMENT_2'](you, npc, ctx)
  M['EOC_PSI_MAINTENANCE_CALORIE_COST_CALCULATOR'](you, npc, ctx)
  if (m.spell_level(you, 'pyrokinetic_aura') >= 1) then
    m.gain_spell_exp(you, 'pyrokinetic_aura', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  else
    m.gain_spell_exp(you, 'pyrokinetic_aura_knack', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  end
  M['EOC_PSIONICS_GAIN_NETHER_ATTUNEMENT_2'](you, npc, ctx)
  M['EOC_PSI_MAINTENANCE_CALORIE_COST_CALCULATOR'](you, npc, ctx)
  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_PYROKIN_BLAZING_AURA_DRAIN'](y, npc, ctx) end, you, U.rng(((((m.spell_level(you, 'pyrokinetic_aura') + m.spell_level(you, 'pyrokinetic_aura_knack')) * 7) + 45) * J.psionic_power_modifiers(you, npc, ctx)), ((((m.spell_level(you, 'pyrokinetic_aura') + m.spell_level(you, 'pyrokinetic_aura_knack')) * 19) + 180) * J.psionic_power_modifiers(you, npc, ctx))))
