C['EOC_PYROKIN_FLAME_IMMUNITY_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  return you:has_effect(U.eid('effect_pyrokinetic_flame_immunity'))
end
M['EOC_PYROKIN_FLAME_IMMUNITY_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PYROKIN_FLAME_IMMUNITY_DRAIN'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'latest_channeled_power_difficulty', 7)
  M['EOC_PSIONICS_GAIN_NETHER_ATTUNEMENT_2'](you, npc, ctx)
  M['EOC_PSI_MAINTENANCE_CALORIE_COST_CALCULATOR'](you, npc, ctx)
  m.gain_spell_exp(you, 'pyrokinetic_flame_immunity', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_PYROKIN_FLAME_IMMUNITY_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'pyrokinetic_flame_immunity') * 11) + 90) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'pyrokinetic_flame_immunity') * 47) + 570) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
C['EOC_PYROKIN_FLAME_IMMUNITY_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (not you:has_effect(U.eid('effect_pyrokinetic_flame_immunity')))
end
M['EOC_PYROKIN_FLAME_IMMUNITY_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PYROKIN_FLAME_IMMUNITY_INITIATE'](you, npc, ctx) then
    M['EOC_PYROKIN_REMOVE_FLAME_IMMUNITY'](you, npc, ctx)
    return false
  end
  U.msg(you, 'The nearby air loses any heat.', MsgType.good, ctx)
  M['EOC_POWER_MAINTENANCE_PLUS_ONE'](you, npc, ctx)
  U.add_effect(you, 'effect_pyrokinetic_flame_immunity', 'PERMANENT', nil, nil)
  util.queue_eoc(function(y) M['EOC_PYROKIN_FLAME_IMMUNITY_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'pyrokinetic_flame_immunity') * 11) + 90) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'pyrokinetic_flame_immunity') * 47) + 570) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
