M['EOC_PYROKIN_INTENSIFY_FLAMES'] = function(you, npc, ctx)
  ctx = ctx or {}
  ctx['pyrokin_intensify_flames_target'] = U.query_tile(you, {range = U.clamp(((((m.spell_level(you, 'pyrokinetic_intensify_flames') + m.spell_level(you, 'pyrokinetic_intensify_flames_knack')) * 1.1) + 3) * J.psionic_power_modifiers(you, npc, ctx)), 1, 70), msg = 'Choose target.'})
  if not ctx['pyrokin_intensify_flames_target'] then return false end
  if U.has_field(ctx['pyrokin_intensify_flames_target'], 'fd_fire') then
    U.set_field(ctx['pyrokin_intensify_flames_target'], 'fd_fire', 1, 0)
  end
  U.cast_spell(you, 'pyrokinetic_intensify_flames_target_creature', nil, ctx['pyrokin_intensify_flames_target'])
  return true
end
C['EOC_PYROKIN_LEARNING_AOE_BLAST'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (you:has_trait(U.mid('PYROKINETIC')) and (V.uget(you, 'psi_learning_counter') == 1) and (U.test_eoc(C, 'EOC_CONDITION_ODDS_OF_RANDOM_TIER_THREE_POWER_INSIGHT', you, npc, ctx) or (((m.spell_level(you, 'pyrokinetic_flamethrower') >= 12) or (m.spell_level(you, 'pyrokinetic_blast') >= 6)) and ((m.spell_level(you, 'pyrokinetic_thermogenesis') >= 10) or (m.spell_level(you, 'pyrokinetic_flame_immunity') >= 6)))) and U.test_eoc(C, 'EOC_PSI_LEARNING_BANNED_EFFECTS', you, npc, ctx) and (m.spell_level(you, 'pyrokinetic_aoe_blast') <= 0) and (not you:knows_recipe(RecipeId.new('practice_pyrokinetic_aoe_blast'))))
end
M['EOC_PYROKIN_LEARNING_AOE_BLAST'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PYROKIN_LEARNING_AOE_BLAST'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'psi_learning_counter', 0)
  you:learn_recipe(RecipeId.new('practice_pyrokinetic_aoe_blast'))
  U.msg(you, 'Use of your powers has led to an insight.  You could build the heat up around yourself quickly enough to cause an expanding explosion and protect yourself from its effects, if you can figure out the proper technique.', MsgType.neutral, ctx)
  return true
end
C['EOC_PYROKIN_LEARNING_AURA'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (you:has_trait(U.mid('PYROKINETIC')) and (V.uget(you, 'psi_learning_counter') == 1) and (U.test_eoc(C, 'EOC_CONDITION_ODDS_OF_RANDOM_TIER_TWO_POWER_INSIGHT', you, npc, ctx) or (((m.spell_level(you, 'pyrokinetic_thermogenesis') >= 5) or (m.spell_level(you, 'pyrokinetic_flamethrower') >= 6)) and (m.spell_level(you, 'pyrokinetic_cloak') >= 8) and (m.spell_level(you, 'pyrokinetic_eruption') >= 7))) and U.test_eoc(C, 'EOC_PSI_LEARNING_BANNED_EFFECTS', you, npc, ctx) and (m.spell_level(you, 'pyrokinetic_aura') <= 0) and (not you:knows_recipe(RecipeId.new('practice_pyrokinetic_aura'))))
end
M['EOC_PYROKIN_LEARNING_AURA'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PYROKIN_LEARNING_AURA'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'psi_learning_counter', 0)
  you:learn_recipe(RecipeId.new('practice_pyrokinetic_aura'))
  U.msg(you, 'Use of your powers has led to an insight.  You could heat the air around yourself burning hot, injuring anyone engaged in melee combat with you, if you can figure out the proper technique.', MsgType.neutral, ctx)
  return true
end
