C['EOC_PYROKIN_MATRIX_AWAKENING_FAILURE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return true
end
M['EOC_PYROKIN_MATRIX_AWAKENING_FAILURE'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  You feel a pleasant heat in your veins, but as you look down at your hands, the heat turns into a searing pain.  The crystal flashes once, the light drives spikes into your brain, and then goes dark.', MsgType.neutral, ctx)
  U.add_effect(you, 'psionic_overload', TimeDuration.from_hours(1), nil, nil)
  U.add_effect(you, 'stunned', TimeDuration.from_turns(10), nil, nil)
  util.queue_eoc(function(y) M['EOC_PYROKIN_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  return true
end
C['EOC_PYROKIN_MATRIX_AWAKENING_SUCCESS'] = function(you, npc, ctx)
  ctx = ctx or {}
  return true
end
M['EOC_PYROKIN_MATRIX_AWAKENING_SUCCESS'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  The crystal begins glowing, the faint light at its core gradually brightening, first shedding light on your surroundings and then throwing everything into sharp relief.  As it blazes in your hands, it begins growing slowly warmer.  The warmth spreads down your arms and across your entire body, filling it with a comfortable heat, and then the air around you takes on the heat and the light.  The air wavers like a summer haze, but even as it sparks and flames dance on the air, you feel only a comfortable warmth.  You reach out your free hand, letting the fire play between your fingers, and when the crystal\'s glow dims and fades into nothingness, you don\'t even notice it.', MsgType.neutral, ctx)
  M['EOC_PSI_AWAKENING_PYROKINESIS_FINALIZATION'](you, npc, ctx)
  U.add_effect(you, 'effect_pyrokinetic_cloak', TimeDuration.from_minutes(5), nil, nil)
  U.add_effect(you, 'effect_pyrokinetic_aura', TimeDuration.from_minutes(5), nil, nil)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  util.queue_eoc(function(y) M['EOC_PYROKIN_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
  return true
end
C['EOC_PYROKIN_POTION'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (not you:has_trait(U.mid('CANNOT_GAIN_PSIONICS')))
end
M['EOC_PYROKIN_POTION'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_PYROKIN_POTION'](you, npc, ctx) then
    U.msg(you, 'You drink the concoction.', MsgType.neutral, ctx)
    U.add_effect(you, 'effect_matrix_potion_headblind', U.rng_dur(TimeDuration.from_hours(6), TimeDuration.from_hours(15)), nil, nil)
    return false
  end
  U.msg(you, 'You drink the concoction.', MsgType.neutral, ctx)
  you:remove_effect(U.eid('effect_pyrokin_potion_comedown'))
  U.add_effect(you, 'effect_pyrokin_potion', TimeDuration.from_hours(30), nil, nil)
  U.add_effect(you, 'effect_matrix_potion_nether_boost', TimeDuration.from_hours(30), nil, nil)
  util.queue_eoc(function(y) M['EOC_PYROKIN_POTION_COMEDOWN'](y, npc, ctx) end, you, U.rng(43200, 108000))
  return true
end
C['EOC_PYROKIN_POTION_COMEDOWN'] = function(you, npc, ctx)
