M['EOC_REALITY_TEAR_CHECKER'] = function(you, npc, ctx)
  ctx = ctx or {}
  ctx['reality_tear_adjustment'] = 0
  if U.test_eoc(C, 'EOC_CONDITION_CAUGHT_IN_NETHER_WEATHER', you, npc, ctx) then
    ctx['reality_tear_adjustment'] = ((ctx['reality_tear_adjustment'] or 0)) + (20)
  end
  if U.test_eoc(C, 'EOC_CONDITION_YOU_ARE_IN_NETHER_LOCATION', you, npc, ctx) then
    ctx['reality_tear_adjustment'] = ((ctx['reality_tear_adjustment'] or 0)) + (10)
  end
  if U.test_eoc(C, 'EOC_CONDITION_NEAR_NETHER_RELATED_LOCATION', you, npc, ctx) then
    ctx['reality_tear_adjustment'] = ((ctx['reality_tear_adjustment'] or 0)) + (5)
  end
  U.msg(you, 'Your adjusted chance is <context_val:reality_tear_adjustment>.', MsgType.debug, ctx)
  if U.x_in_y(((m.attunement(you) / 25) + (ctx['reality_tear_adjustment'] or 0)), 100) then
    U.cast_spell_targeted(you, 'teleport_reality_tear_permanent', m.spell_level(you, 'teleport_reality_tear'), math.min((((m.spell_level(you, 'teleport_reality_tear') * 1.3) + 2) * J.psionic_power_modifiers(you, npc, ctx)), 80), '[Ψ]Reality Tear: choose target.')
  else
    U.cast_spell_targeted(you, 'teleport_reality_tear_temporary', m.spell_level(you, 'teleport_reality_tear'), math.min((((m.spell_level(you, 'teleport_reality_tear') * 1.3) + 2) * J.psionic_power_modifiers(you, npc, ctx)), 80), '[Ψ]Reality Tear: choose target.')
  end
  return true
end
