  if (U.unported_num('EOC_SILENT_ONE_DETECT_PSIONIC_ACTIVITY', 'n_val:anger') > 20) then
    ctx['loc'] = npc:get_pos_ms()
    U.cast_spell(npc, 'silent_one_polymorph_to_hostile', nil, ctx['loc'])
  end
  return true
end
