M['EOC_SILENT_ONE_DRAINING_POWER'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_SILENT_ONE_DRAINING_POWER'](you, npc, ctx) then
    U.unported('EOC_SILENT_ONE_DRAINING_POWER', 'write u_val:anger')
    U.unported('EOC_SILENT_ONE_DRAINING_POWER', 'write u_val:morale')
    U.add_effect(you, 'effect_silent_one_monster_drain', TimeDuration.from_turns(1800), nil, nil)
    return false
  end
  U.add_morale(you, 'morale_silent_one_drain', U.round(-5), U.round(-200), TimeDuration.from_hours(24), TimeDuration.from_hours(12))
  U.unported('EOC_SILENT_ONE_DRAINING_POWER', 'lvalue u_health')
  if (m.maintained_count(you) >= 1) then
    you:set_stored_kcal(U.round((you:get_stored_kcal()) - ((U.rng(0, 125) + 250))))
  else
    you:set_stored_kcal(U.round((you:get_stored_kcal()) - (125)))
  end
  you:set_stored_kcal(U.round((you:get_stored_kcal()) + (125)))
  U.msg(you, 'You feel a sudden wave of fatigue!', MsgType.bad, ctx)
  U.unported('EOC_SILENT_ONE_DRAINING_POWER', 'write n_val:anger')
  return true
end
