C['EOC_TELEKINETIC_AWAKENING_KNACK_HANDLING'] = function(you, npc, ctx)
  ctx = ctx or {}
  return you:has_trait(U.mid('PSYCHIC_KNACK'))
end
M['EOC_TELEKINETIC_AWAKENING_KNACK_HANDLING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEKINETIC_AWAKENING_KNACK_HANDLING'](you, npc, ctx) then
    return false
  end
  if (m.spell_level(you, 'telekinetic_pull_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'telekinetic_pull_knack')
    U.set_spell_level(you, 'telekinetic_pull', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telekinetic_pull_knack', -(1))
  end
  if (m.spell_level(you, 'telekinetic_push_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'telekinetic_push_knack')
    U.set_spell_level(you, 'telekinetic_push', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telekinetic_push_knack', -(1))
  end
  if (m.spell_level(you, 'telekinetic_slam_down_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'telekinetic_slam_down_knack')
    U.set_spell_level(you, 'telekinetic_slam_down', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telekinetic_slam_down_knack', -(1))
  end
  if (m.spell_level(you, 'telekinetic_wave_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'telekinetic_wave_knack')
    U.set_spell_level(you, 'telekinetic_wave', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telekinetic_wave_knack', -(1))
  end
  if (U.spell_count(you, nil) == 0) then
    U.unset_mutation(you, 'PSYCHIC_KNACK')
  end
  return true
end
