M['EOC_TELEKINETIC_PUSH_DIRECTION_PICKER'] = function(you, npc, ctx)
  ctx = ctx or {}
  ctx['u_pos'] = you:get_pos_ms()
  U.msg(you, 'Select direction.', MsgType.neutral, ctx)
  U.unported('EOC_TELEKINETIC_PUSH_DIRECTION_PICKER', '?mirror_coordinates')
  U.knockback(you, ctx['push_direction_correct'], V.uget(you, 'telekinesis_shove_spell_level'), 1, (1 + (V.uget(you, 'telekinesis_shove_spell_level') * 0.4)))
  return true
end
C['EOC_TELEKINETIC_PUSH_DOWN_CHECKER'] = function(you, npc, ctx)
