end
M['EOC_TELEKINETIC_PUSH_DOWN_CHECKER'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEKINETIC_PUSH_DOWN_CHECKER'](you, npc, ctx) then
    U.msg(npc, 'You attempt to shove your target but they are too heavy!', MsgType.bad, ctx)
    return false
  end
  U.add_effect(you, 'downed', TimeDuration.from_turns(2), nil, nil)
  U.msg(npc, 'You shove your target off their feet.', MsgType.good, ctx)
  return true
end
C['EOC_TELEKINETIC_THROW_WEIGHT_HANDLER'] = function(you, npc, ctx)
  ctx = ctx or {}
  return true
end
M['EOC_TELEKINETIC_THROW_WEIGHT_HANDLER'] = function(you, npc, ctx)
  ctx = ctx or {}
  V.uset(you, 'telekinesis_intelligence', ((m.int(npc) + 10) / 20))
  V.uset(you, 'nether_attunement_telekinesis_scaling', V.uget(npc, 'nether_attunement_power_scaling'))
  V.uset(you, 'weight_ratio', (((((V.uget(you, 'telekinesis_power_level') * V.uget(you, 'telekinesis_weight_ratio')) * V.uget(you, 'telekinesis_intelligence')) * V.uget(you, 'nether_attunement_telekinesis_scaling')) + (V.uget(you, 'telekinesis_weight_ratio') / 2)) / (U.weight(you) / 1000000)))
  V.uset(you, 'telekinesis_shove_spell_level', U.clamp(((V.uget(you, 'weight_ratio') - 1) * 2), 0, 30))
  U.msg(you, 'The weight ratio is <u_val:weight_ratio>.', MsgType.debug, ctx)
  U.msg(you, 'The effective spell level is <u_val:telekinesis_shove_spell_level>.', MsgType.debug, ctx)
  ctx['loc'] = you:get_pos_ms()
  if (V.uget(you, 'telekinesis_shove_spell_level') < 1) then
    M['EOC_TELEKINETIC_PUSH_DOWN_CHECKER'](you, npc, ctx)
  else
    if (V.uget(you, 'telekinesis_push_pull_selector') == -(1)) then
      V.uset(you, 'telekinesis_shove_spell_level', (V.uget(you, 'telekinesis_shove_spell_level')) * (V.uget(you, 'telekinesis_push_pull_selector')))
      U.msg(you, 'The effective spell level for pulling is <u_val:telekinesis_shove_spell_level>.', MsgType.debug, ctx)
      V.uset(npc, 'telekinesis_shove_spell_level', V.uget(you, 'telekinesis_shove_spell_level'))
      U.cast_spell(npc, 'telekinetic_force_shove_real', nil, ctx['loc'])
      M['EOC_TELEKINETIC_PUSH_DOWN_CHECKER'](you, npc, ctx)
    else
      if U.is_avatar(npc) then
        U.msg(npc, 'You hurl your target.', MsgType.good, ctx)
        M['EOC_TELEKINETIC_PUSH_DIRECTION_PICKER'](you, npc, ctx)
      else
        U.cast_spell(npc, 'telekinetic_force_shove_real', nil, ctx['loc'])
        M['EOC_TELEKINETIC_PUSH_DOWN_CHECKER'](you, npc, ctx)
      end
    end
  end
  return true
end
