  return true
end
M['EOC_TELEKIN_MATRIX_AWAKENING_SUCCESS'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  You release your grasp on the crystal but it doesn\'t fall.  It floats, supported on nothingness, and as you watch it you become aware of the connections between objects.  Gravity, attraction and repulsion, reveal themselves--you can see the weakened influence of gravity on the crystal, and with a thought you nudge it slightly.  The crystal floats up in the air, stretching the connections between it at the ground, before they adjust to its new place.  You tug on the connections, rotating the crystal, moving it from left to right, and as the light within it slowly fades away, you let go and the crystal drops back to your hand.', MsgType.neutral, ctx)
  M['EOC_PSI_AWAKENING_TELEKINESIS_FINALIZATION'](you, npc, ctx)
  U.add_effect(you, 'effect_telekinetic_armor', TimeDuration.from_minutes(1), nil, nil)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  util.queue_eoc(function(y) M['EOC_TELEKIN_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
  return true
end
