M['EOC_TELEKIN_WAVE_TARGETS'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEKIN_WAVE_TARGETS'](you, npc, ctx) then
    return false
  end
  ctx['player_position'] = npc:get_pos_ms()
  V.uset(you, 'telekinesis_power_level', (m.spell_level(npc, 'telekinetic_wave') + m.spell_level(npc, 'telekinetic_wave_knack')))
  V.uset(you, 'telekinesis_intelligence', ((m.int(npc) + 10) / 20))
  V.uset(you, 'nether_attunement_telekinesis_scaling', V.uget(npc, 'nether_attunement_power_scaling'))
  V.uset(you, 'telekinesis_weight_ratio', 55)
  V.uset(you, 'weight_ratio', (((((V.uget(you, 'telekinesis_power_level') * V.uget(you, 'telekinesis_weight_ratio')) * V.uget(you, 'telekinesis_intelligence')) * V.uget(you, 'nether_attunement_telekinesis_scaling')) + (V.uget(you, 'telekinesis_weight_ratio') / 2)) / (U.weight(you) / 1000000)))
  V.uset(you, 'telekinesis_shove_spell_level', U.clamp(((V.uget(you, 'weight_ratio') - 1) * 2), 0, 30))
  if U.x_in_y((V.uget(you, 'weight_ratio') * 1000), 1000) then
    U.add_effect(you, 'downed', TimeDuration.from_turns(2), nil, nil)
  end
  U.knockback(you, ctx['player_position'], V.uget(you, 'telekinesis_shove_spell_level'), 2, (1 + (V.uget(you, 'telekinesis_shove_spell_level') * 0.4)))
  return true
end
