    ctx['temp_var'] = m.spell_level(you, 'telepathic_shield_knack')
    U.set_spell_level(you, 'telepathic_shield', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telepathic_shield_knack', -(1))
