    U.set_spell_level(you, 'telepathic_morale', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telepathic_morale_knack', -(1))
  end
  if (m.spell_level(you, 'telepathic_blast_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'telepathic_blast_knack')
    U.set_spell_level(you, 'telepathic_blast', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telepathic_mesmerize_knack', -(1))
  end
  if (m.spell_level(you, 'telepathic_mesmerize_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'telepathic_mesmerize_knack')
    U.set_spell_level(you, 'telepathic_mesmerize', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telepathic_mesmerize_knack', -(1))
  end
  if (m.spell_level(you, 'telepathic_animal_mind_control_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'telepathic_animal_mind_control_knack')
    U.set_spell_level(you, 'telepathic_animal_mind_control', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telepathic_animal_mind_control_knack', -(1))
  end
  if (m.spell_level(you, 'telepathic_invisibility_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'telepathic_invisibility_knack')
    U.set_spell_level(you, 'telepathic_invisibility', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telepathic_invisibility_knack', -(1))
  end
  if (m.spell_level(you, 'telepathic_blast_radius_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'telepathic_blast_radius_knack')
    U.set_spell_level(you, 'telepathic_blast_radius', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'telepathic_blast_radius_knack', -(1))
  end
  if (U.spell_count(you, nil) == 0) then
    U.unset_mutation(you, 'PSYCHIC_KNACK')
  end
  return true
end
