M['EOC_TELEPATHIC_DAMAGE_PSYSHIELD_CHECK'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATHIC_DAMAGE_PSYSHIELD_CHECK'](you, npc, ctx) then
    M['EOC_TELEPATHIC_DAMAGE_STUN_CHANCE'](you, npc, ctx)
    M['EOC_TELEPATHIC_DAMAGE_DAZED_CHANCE'](you, npc, ctx)
    M['EOC_TELEPATHIC_DAMAGE_KNOCKDOWN_CHANCE'](you, npc, ctx)
    return false
  end
  M['EOC_TELEPATHIC_DAMAGE_PSYSHIELD_CHECK_2'](you, npc, ctx)
  return true
end
C['EOC_TELEPATHIC_DAMAGE_PSYSHIELD_CHECK_2'] = function(you, npc, ctx)
  ctx = ctx or {}
  return U.x_in_y(1, 2)
end
M['EOC_TELEPATHIC_DAMAGE_PSYSHIELD_CHECK_2'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATHIC_DAMAGE_PSYSHIELD_CHECK_2'](you, npc, ctx) then
    npc:remove_effect(U.eid('effect_psyshield_protection'))
    U.cast_spell(npc, 'telepathic_self_damage', nil, nil)
    U.msg(npc, 'Your mind reels!', MsgType.bad, ctx)
    return false
  end
  U.msg(npc, 'Your head prickles.  It feels like spiders crawling across the surface of your brain.', MsgType.bad, ctx)
  npc:remove_effect(U.eid('effect_psyshield_protection'))
  return true
end
C['EOC_TELEPATHIC_DAMAGE_STUN_CHANCE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (U.x_in_y(1, 3) and ((ctx['damage_taken'] or 0) > 0) and (not U.has_creature_flag(npc, 'HIVE_MIND')) and (not U.has_creature_flag(npc, 'TEEP_IMMUNE')) and (not U.has_creature_flag(npc, 'TEEPSHIELD')))
end
M['EOC_TELEPATHIC_DAMAGE_STUN_CHANCE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATHIC_DAMAGE_STUN_CHANCE'](you, npc, ctx) then
    return false
  end
  U.add_effect(npc, 'psi_stunned', TimeDuration.from_turns(1), nil, nil)
  return true
end
C['EOC_TELEPATHIC_DAMAGE_STUN_HIVE_CHANCE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (U.x_in_y(1, 6) and ((ctx['damage_taken'] or 0) > 0) and U.has_creature_flag(npc, 'HIVE_MIND'))
end
M['EOC_TELEPATHIC_DAMAGE_STUN_HIVE_CHANCE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATHIC_DAMAGE_STUN_HIVE_CHANCE'](you, npc, ctx) then
    return false
  end
  U.add_effect(npc, 'psi_stunned', TimeDuration.from_turns(1), nil, nil)
  return true
end
C['EOC_TELEPATHIC_MENTAL_ENGINEERING_SELECTOR'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (U.spell_level_sum(you, tostring('TELEPATH')) > 100)
end
M['EOC_TELEPATHIC_MENTAL_ENGINEERING_SELECTOR'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATHIC_MENTAL_ENGINEERING_SELECTOR'](you, npc, ctx) then
    U.msg(you, 'You feel that you need to be an incredibly powerful telepath to make this work', MsgType.neutral, ctx)
    return false
  end
  local _pick = U.select_eoc_menu('', {'EOC_TELEPATH_MENTAL_ENGINEERING_UNCARING_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_UNCARING_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_PACIFIST_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_NUMB_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_NUMB_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_NYCTOPHOBIA_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_VANITY_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_PICKYEATER_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_SOCIAL1_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_SOCIAL1_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_SOCIAL2_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_SOCIAL2_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_ASOCIAL1_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_ASOCIAL1_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_ASOCIAL2_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_ASOCIAL2_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_HATES_WATER_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_OUTDOORSMAN_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_BRAWLER_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_WAYFARER_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_NOMAD_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_NOMAD2_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_NOMAD3_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_SQUEAMISH_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_PROF_DICEMASTER_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_PYROMANIA_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_PYROMANIA_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_TRUTHTELLER_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_LIAR_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_VEGAN_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_STRICT_HUMANITARIAN_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_STRICT_HUMANITARIAN_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_CANNIBAL_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_CANNIBAL_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_MOODSWINGS_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_SAVANT_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_SAVANT_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_HOARDER_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_SCHIZOPHRENIC_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_SLOWREADER_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_FASTREADER_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_ADDICTIVE_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_NONADDICTIVE_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_FORGETFUL_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_GOODMEMORY_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_PROJUNK_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_PROJUNK_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_HATES_BOOKS_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_LOVES_BOOKS_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_SLOWLEARNER_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_FASTLEARNER_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_DISORGANIZED_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_PACKMULE_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_BADTEMPER_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_OPTIMISTIC_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_SEASONAL_AFFECTIVE_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_UNOBSERVANT_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_EAGLEEYED_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_MASOCHIST_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_MASOCHIST_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_SPIRITUAL_01', 'EOC_TELEPATH_MENTAL_ENGINEERING_SPIRITUAL_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_TABLEMANNERS_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_INATTENTIVE_02', 'EOC_TELEPATH_MENTAL_ENGINEERING_CANCEL'}, {'Become Uncaring', 'Stop being Uncaring', 'Remove your Pacifist desires', 'Become Numb', 'Stop being Numb', 'Conquer Nyctophobia', 'Stop your Vanity', 'Stop being a Picky Eater', 'Push Extroversion', 'Stop Extroversion', 'Force Sociability', 'Tone down Sociability', 'Push Introversion', 'Stop Introversion', 'Become a Loner', 'Stop being a Loner', 'Stop Hating Water', 'Become an Outdoorsman', 'Expand beyond Brawling', 'Reject Wayfaring', 'Reject the Nomadic life', 'Overcome your Antsy-ness', 'Prevent Restlessness', 'Lose your Squeamishness', 'Pretend to be a Dungeon Master', 'Embrace Pyromania', 'Lose your Pyromania', 'Devalue Truth Telling', 'Become a Liar', 'Reject Veganism', 'Be a Strict Humanitarian', 'Stop being a Strict Humanitarian', 'Embrace Cannibalism', 'Reject Cannibalism', 'Stop your Mood Swings', 'Become a Savant', 'Stop being a Savant', 'Stop Hoarding', 'Fix Kaluptic Psychosis', 'Improve your Slow Reading', 'Speed up your Reading', 'Remove your Addictiveness', 'Prevent Addiction', 'Stop being Forgetful', 'Get a Good Memory', 'Build a Sweet Tooth', 'Break your Sweet Tooth', 'Stop Hating Books', 'Start Loving Books', 'Fix your Slow Learning', 'Improve your Learning', 'Stop being Disorganized', 'Become a Packmule', 'Improve your Temper', 'Be Optimistic!', 'Cure your Seasonal Affective Disorder', 'Cure Topographagnosia', 'Become a Scout', 'Become a Masochist', 'Stop being a Masochist', 'Embrace your Spirituality', 'Reject your Spirituality', 'Neglect your Table Manners', 'Fix your Inattentiveness', 'cancel'}, {'You will no longer care about harming your fellow humans and other innocent creatures.', 'The suffering of your fellows will affect you.  How could you possibly live like that?', 'Lose your pacifistic desires to do no harm.  Even thinking about what you might do afterwards unnerves you.', 'Stop caring about all the little ups and downs of the Cataclysm.  You feel this is only possible due to your extensive consumption of Medical mutagen.', 'Let yourself be affected by all the ups and downs of the Cataclysm.  Hopefully more up than down.', 'Perform a comprehensive and corrective surgery to cure your fear of the dark.  No longer will you be paralyzed by errant shadows.', 'Deflate your perfectly logical, justified, and factual acknowledgement of your beauty.  How could you deprive everyone else of your looks?', 'Rather than expanding your palette the normal way, use your incredible telepathic powers to force yourself to be OK with untasty looking food.  At least it gets the job done.', 'Force yourself to appreciate the company of others by making yourself an extrovert.  Hopefully you\'ll be able to find people to interact with.', 'Stop yourself from enjoying the company of others by removing your extroversion.  It\'s not like there\'s anybody around anyways, right?', 'Force yourself to require the company of others by making yourself incredibly sociable.  Hopefully you have friends.', 'Work on yourself by stopping your need for others\' presence.  A workable lifestyle turned problem which started with the death of everyone you knew and loved.', 'Make sure that you\'re happy alone by making yourself an introvert.  With near everyone dead, this mindset just got a lot more viable.', 'Stop yourself from enjoying being alone by removing your introversion.  You now feel positively neutral.', 'Force yourself to hate interacting with others.  What would have been a debilitating mentality in pre-Cataclysm life might actually help you.  What\'s the chance you\'ll actually have to talk to someone now?', 'Your instinctive hatred of social interaction is probably a bit much.  For all that meeting other survivors is rare you should probably be more receptive to their presence.', 'As much as you currently hate water, you can begrudgingly accept that it would be easier if you didn\'t feel that way.', 'You now have a lot more reasons to be outside while it\'s raining.  Being wet doesn\'t really hurt you physically, and with your telepathic power you can make sure it doesn\'t hurt you mentally either.', 'Replace therapy and many other normal, healthy options for getting over your inability to use guns.  At least this method is quick.', 'Drastic times require dramatic measures.  Whatever your reason for not driving, you can get over it with a small dose of major psychic surgery.', 'As much as you love travelling you can see the benefits of staying in one place.  Psychically remove your desire to keep exploring.', 'As much as it hurts you, you just cannot get over the dullness of familiar places.  With a bit of psychic surgery, that dullness can get a good bit brighter.', 'Even taking the time to consider this alteration of your head is making you incredibly unhappy at your lack of travel.  You should really fix this.', 'Logically speaking, your refusal to wear tainted clothing really isn\'t that bad.  There may be some benefit to reducing your squeamishness, though.', 'Finding time to DM a game is probably not going to happen again.  Even so, by spending an inordinate amount of time studying a DM\'ing guide while under the effect of your psychic powers you think you can get some ideas on how to do it again but quicker.', 'The government is gone and so are the owners of all these buildings.  And trees.  And really everything flammable.  You think you can make yourself enjoy the act a lot more than you may already do, but this may have some side effects.', 'As fun as it is, you can begrudgingly agree that there\'s better things to do than setting fires.  Put a hypothetical therapist out of business with your psychic powers and fix that.', 'Being able to lie could be an important part of your life… if there was even anyone to lie to.  You doubt this would help you much.', 'There\'s still a couple of survivors around, and being good at lying to them might give you some opportunities you otherwise would lack.  It might also get you in trouble.', 'Even the thought of doing this makes you incredibly uncomfortable, but of all the reasons to quit veganism, the complete destruction of your entire world probably qualifies.', 'Logically speaking, those things that kind of look human really aren\'t.  It might currently feel uncomfortable, but it\'s hard to think of a real argument against eating them.  May as well get over your emotions.  Telepathically!', 'You feel just fine eating those not-humans, but a tiny part of your brain tells you that this might be a slippery slope.  It might not be logical, but you can stop this immediately.', 'Completely disgusting, and potentially quite unhealthy.  However, given the times it may be your only option.  Can you force yourself to enjoy the taste of human flesh?', 'As tasty as humans are, it\'s gotten you some negative looks from other survivors when you accidently referred to your \'taste.\'  Are you willing to change yourself just to meet their expectations?', 'Help balance your mood by fixing the centers of your brain that are responsible for regulating it.  Be a little more at peace with yourself.', 'You\'ve heard stories of people who heavily specialize in certain skills at the expense of all others.  With a bit of work, you think you can replicate this in yourself.', 'Can you really care about all those other things that don\'t matter or even make that much sense.  With a bit of telepathic brain surgery you can!', 'You can begrudgingly admit that an old candy wrapper might not be the most useful thing in the world.  Help yourself physically drop it by mentally dropping your hording sensibilities.', 'At least one of the voices recommended you do this, and they seemed trustworthy.', 'It takes you a while to process information, far longer than the average person.  You think you\'ve identified the locations of your brain responsible for this, and with a bit of telepathic power you can fix that.', 'With some deep analysis of how your brain works while reading with your Speed Reading power, you think you can replicate some of the efficiency caused by it.  This will allow you to permanently read quicker.', 'Help yourself stop getting addicted to things by analyzing the relevant pathways and closing them up.  You won\'t be extra addictive anymore, but you won\'t necessarily have any special resistance either.', 'Increase your inhibitions with a bit of psychic surgery.  Even beyond the normal reasons, a good supply of alcohol and really any other addictive substance is hard to come by nowadays.  Make sure you don\'t need them any more than usual.', 'Fix your damaged memory regions to allow you to remember all of that important stuff better.', 'Improve the memory regions within your brain, allowing you to recall information far more easily.  Help make sure you don\'t forget things ever again.', 'Sugar already tastes pretty good.  You can increase those feelings and make it taste even better.', 'Sugar may taste amazing, but eating so much of it probably isn\'t healthy.  Enforce your new diet by making it taste worse.', 'As annoying as books may be, you think that it would be useful to not be so bored while reading them.  Fix that with psychic power.', 'Reading has been one of the most important skills that has let humanity rise as far as it once did.  Make sure you spend more time doing it by making sure that you love it.', 'Improve the areas relegated to learning new information in your brain that you\'ve noticed are operating a little poorly.  This has no downsides.', 'Take some notes on how you brain functions while you\'re in concentration trances and permanently replicate a small part of that efficiency in your head to help you learn everything quicker.', 'Improve your 3D awareness and planning by adjusting your brain.  There\'s definitely ways of packing that you\'re currently missing.', 'Dramatically improve your 3D awareness by making several efficiency alterations to your brain.  Seeing how things fit together will get a lot easier.', 'You already have enough to be angry about right now, you don\'t need your brain naturally being pissed off as well.  Instead of pills or therapy, use your telepathic powers!', 'With a couple of notes from your Mood Stabilization power, you can permanently alter your brain to make you happier.', 'Winter already has some real issues for your survival.  There\'s no need for you to be depressed on top of it.  Fix that up with some intricate mental surgery.', 'Fix your inability to remember locations and direct yourself by connecting locations of your brain that were erroneously disconnected.', 'With a deep analysis of how you remember locations you think you can improve your ability to do so.', 'Rewire your way of feeling pain into something slightly positive.  It will still be incredibly distracting and debilitating, but at least you\'ll enjoy it.  Hopefully not enough to intentionally seek it out.', 'Your enjoyment of pain has lead to too many bad decisions.  Get rid of it before a zombie gets rid of you.', 'The dream of a person struggling with their faith.  Force yourself to see spirituality in everything by mentally adjusting your brain to mirror somebody else\'s faith.  It may not be the typical way of finding spirituality, but you reckon the end result will be similar.', 'Even your immense spirituality cannot compete with the horrors around you.  Intentionally lose a major element of who you are so you don\'t have to deal with it.', 'Use your psychic powers to forget all of your memories mandating you eat with good manners; hopefully, you won\'t lose anything else important.', 'Fix up the regions of your brain responsible for predicting the actions of others.  A surprisingly comprehensive surgery.', 'Do something else'}, you, npc, ctx, true)
  if not _pick then return false end
  M[_pick](you, npc, ctx)
  return true
end
C['EOC_TELEPATH_CONCENTRATION_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  return you:has_effect(U.eid('effect_telepathic_learning_bonus'))
end
M['EOC_TELEPATH_CONCENTRATION_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATH_CONCENTRATION_DRAIN'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'latest_channeled_power_difficulty', 1)
  M['EOC_PSIONICS_GAIN_NETHER_ATTUNEMENT_2'](you, npc, ctx)
  M['EOC_PSI_MAINTENANCE_CALORIE_COST_CALCULATOR'](you, npc, ctx)
  m.gain_spell_exp(you, 'telepathic_concentration', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_TELEPATH_CONCENTRATION_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'telepathic_concentration') * 132) + 560) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'telepathic_concentration') * 605) + 1033) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
C['EOC_TELEPATH_CONCENTRATION_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (not you:has_effect(U.eid('effect_telepathic_learning_bonus')))
end
M['EOC_TELEPATH_CONCENTRATION_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATH_CONCENTRATION_INITIATE'](you, npc, ctx) then
    M['EOC_TELEPATH_REMOVE_TELEPATHIC_CONCENTRATION'](you, npc, ctx)
    return false
  end
  U.msg(you, 'Your vision narrows to what is directly in front of you as you concentrate.', MsgType.good, ctx)
  M['EOC_POWER_MAINTENANCE_PLUS_ONE'](you, npc, ctx)
  M['EOC_VITAKIN_REMOVE_NO_NEED_FOR_SLEEP'](you, npc, ctx)
  U.add_effect(you, 'effect_telepathic_learning_bonus', 'PERMANENT', nil, nil)
  util.queue_eoc(function(y) M['EOC_TELEPATH_CONCENTRATION_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'telepathic_concentration') * 132) + 560) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'telepathic_concentration') * 605) + 1033) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
C['EOC_TELEPATH_CRYSTAL_DRAINING'] = function(you, npc, ctx)
  ctx = ctx or {}
  return U.has_item(you, 'matrix_crystal_telepathy')
end
M['EOC_TELEPATH_CRYSTAL_DRAINING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATH_CRYSTAL_DRAINING'](you, npc, ctx) then
    return false
  end
  U.unported('EOC_TELEPATH_CRYSTAL_DRAINING', 'u_consume_item')
  you:create_item(ItypeId.new('matrix_crystal_drained'), U.round(1))
  return true
end
C['EOC_TELEPATH_LEARNING_AOE_BLAST'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (you:has_trait(U.mid('TELEPATH')) and (V.uget(you, 'psi_learning_counter') == 1) and (U.test_eoc(C, 'EOC_CONDITION_ODDS_OF_RANDOM_TIER_THREE_POWER_INSIGHT', you, npc, ctx) or (((m.spell_level(you, 'telepathic_blast') >= 11) or (m.spell_level(you, 'telepathic_fear') >= 7)) and (m.spell_level(you, 'telepathic_shield') >= 5))) and U.test_eoc(C, 'EOC_PSI_LEARNING_BANNED_EFFECTS', you, npc, ctx) and (m.spell_level(you, 'telepathic_blast_radius') <= 0) and (not you:knows_recipe(RecipeId.new('practice_telepathic_scream'))))
end
M['EOC_TELEPATH_LEARNING_AOE_BLAST'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATH_LEARNING_AOE_BLAST'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'psi_learning_counter', 0)
  you:learn_recipe(RecipeId.new('practice_telepathic_scream'))
  U.msg(you, 'Use of your powers has led to an insight.  You could erase yourself from a target\'s perceptions, making them completely unable to even know that you\'re there, if you can figure out the proper technique.', MsgType.neutral, ctx)
  return true
end
