end
M['EOC_TELEPATH_MENTAL_ENGINEERING_SIDE_EFFECTS'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATH_MENTAL_ENGINEERING_SIDE_EFFECTS'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'mentality_picked', U.rng(1, 32))
  local _sw = V.uget(you, 'mentality_picked')
  if _sw >= 32 then
    U.set_mutation(you, 'INATTENTIVE')
    U.msg(you, 'The emotions on people\'s faces and movements of animals mean nothing to you.  Not in an emotional sense, but because you really don\'t understand them anymore.', MsgType.bad, ctx)
  elseif _sw >= 31 then
    U.set_mutation(you, 'TABLEMANNERS')
    U.msg(you, 'You better make sure you have a fork.', MsgType.bad, ctx)
  elseif _sw >= 30 then
    U.set_mutation(you, 'MASOCHIST')
    U.msg(you, 'Even pinching your skin feels better than it used to.', MsgType.good, ctx)
  elseif _sw >= 29 then
    U.set_mutation(you, 'UNOBSERVANT')
    U.unset_mutation(you, 'EAGLEEYED')
    U.msg(you, 'Where are you?', MsgType.bad, ctx)
  elseif _sw >= 28 then
    U.set_mutation(you, 'SEASONAL_AFFECTIVE')
    U.unset_mutation(you, 'OPTIMISTIC')
    U.unset_mutation(you, 'BADTEMPER')
    U.msg(you, 'You really hope things remain bright and sunny.', MsgType.bad, ctx)
  elseif _sw >= 27 then
    U.set_mutation(you, 'BADTEMPER')
    U.unset_mutation(you, 'OPTIMISTIC')
    U.unset_mutation(you, 'SEASONAL_AFFECTIVE')
    U.msg(you, 'You feel unhappy.', MsgType.bad, ctx)
  elseif _sw >= 26 then
    U.set_mutation(you, 'DISORGANIZED')
    U.unset_mutation(you, 'PACKMULE')
    U.msg(you, 'You think it\'s going to take longer to sort things now.', MsgType.bad, ctx)
  elseif _sw >= 25 then
    U.set_mutation(you, 'SLOWLEARNER')
    U.unset_mutation(you, 'FASTLEARNER')
    U.msg(you, 'Thinking of new ideas just got a good bit harder.', MsgType.bad, ctx)
  elseif _sw >= 24 then
    U.set_mutation(you, 'HATES_BOOKS')
    U.unset_mutation(you, 'LOVES_BOOKS')
    U.msg(you, 'Your desire to read seems lesser.', MsgType.bad, ctx)
  elseif _sw >= 23 then
    U.set_mutation(you, 'FORGETFUL')
    U.unset_mutation(you, 'GOODMEMORY')
    U.msg(you, 'Your memory seems much worse than before.', MsgType.bad, ctx)
  elseif _sw >= 22 then
    U.set_mutation(you, 'ADDICTIVE')
    U.unset_mutation(you, 'NONADDICTIVE')
    U.msg(you, 'Right now, you don\'t feel any change.  Something tells you that touching drugs or alcohol may have just become a worse idea, however.', MsgType.bad, ctx)
  elseif _sw >= 21 then
    U.set_mutation(you, 'SLOWREADER')
    U.unset_mutation(you, 'FASTREADER')
    U.msg(you, 'The words on the page seem more daunting.', MsgType.bad, ctx)
  elseif _sw >= 20 then
    U.set_mutation(you, 'SCHIZOPHRENIC')
    U.msg(you, 'It\'s hard to hear yourself think over all of the voices in your head!', MsgType.bad, ctx)
  elseif _sw >= 19 then
    U.set_mutation(you, 'HOARDER')
    U.msg(you, 'You NEED to make sure that nothing gets left behind.  Every single thing is important.', MsgType.bad, ctx)
  elseif _sw >= 18 then
    U.set_mutation(you, 'SAVANT')
    U.msg(you, 'It\'s hard to even understand how you used to think.  There\'s only one thing that makes sense now.', MsgType.neutral, ctx)
  elseif _sw >= 17 then
    U.set_mutation(you, 'MOODSWINGS')
    U.msg(you, 'You feel that your prior mental balance and peace has ended.', MsgType.bad, ctx)
  elseif _sw >= 16 then
    U.set_mutation(you, 'CANNIBAL')
    U.unset_mutation(you, 'VEGAN')
    U.unset_mutation(you, 'STRICT_HUMANITARIAN')
    U.msg(you, 'Your fellow survivors just got a lot more attractive.  To your taste buds.', MsgType.good, ctx)
  elseif _sw >= 15 then
    U.set_mutation(you, 'STRICT_HUMANITARIAN')
    U.unset_mutation(you, 'VEGAN')
    U.unset_mutation(you, 'CANNIBAL')
    U.msg(you, 'Your palette just got a bit bigger.  Admittedly, how often do you actual encounter these creatures?', MsgType.good, ctx)
  elseif _sw >= 14 then
    U.set_mutation(you, 'VEGAN')
    U.unset_mutation(you, 'STRICT_HUMANITARIAN')
    U.unset_mutation(you, 'CANNIBAL')
    U.msg(you, 'You refuse to even tangentially benefit from the suffering of all those innocent animals!', MsgType.bad, ctx)
  elseif _sw >= 13 then
    U.set_mutation(you, 'TRUTHTELLER')
    U.unset_mutation(you, 'LIAR')
    U.msg(you, 'Thinking about lying to someone just immediately causes you to blush and stutter.  Best not even bother.', MsgType.bad, ctx)
  elseif _sw >= 12 then
    U.set_mutation(you, 'PYROMANIA')
    U.msg(you, 'All that stuff is looking awfully flammable.  Time to get a lighter.  If you have mental powers now, perhaps there\'s something that will let you cause fires with your mind as well?', MsgType.bad, ctx)
  elseif _sw >= 11 then
    U.set_mutation(you, 'SQUEAMISH')
    U.msg(you, 'The blood and cuts that come alongside combat is bad enough.  Putting such disgusting clothes on your skin is absolutely not an option.', MsgType.bad, ctx)
  elseif _sw >= 10 then
    U.set_mutation(you, 'NOMAD3')
    U.unset_mutation(you, 'NOMAD2')
    U.unset_mutation(you, 'NOMAD')
    U.msg(you, 'Keep moving keep moving keep moving keep moving keep moving keep moving!', MsgType.bad, ctx)
  elseif _sw >= 9 then
    U.set_mutation(you, 'WAYFARER')
    U.msg(you, 'There\'s so much that could go wrong if you ever got behind a wheel.  Cars used to be one of the largest causes of death before the Cataclysm, and there\'s definitely no need to decrease your odds by getting in one now!', MsgType.bad, ctx)
  elseif _sw >= 8 then
    U.set_mutation(you, 'BRAWLER')
    U.msg(you, 'Guns are just too scary.  The loud bang, the thought of them being used on you… despite their utility, there\'s no way you could get close to one of them.', MsgType.bad, ctx)
  elseif _sw >= 7 then
    U.set_mutation(you, 'ASOCIAL2')
    U.unset_mutation(you, 'SOCIAL2')
    U.unset_mutation(you, 'ASOCIAL1')
    U.unset_mutation(you, 'SOCIAL1')
    U.msg(you, 'You feel an incredible need to avoid others!', MsgType.bad, ctx)
  elseif _sw >= 6 then
    U.set_mutation(you, 'SOCIAL2')
    U.unset_mutation(you, 'SOCIAL1')
    U.unset_mutation(you, 'ASOCIAL1')
    U.unset_mutation(you, 'ASOCIAL2')
    U.msg(you, 'You feel an enormous need to interact with others!', MsgType.bad, ctx)
  elseif _sw >= 5 then
    U.set_mutation(you, 'PICKYEATER')
    U.msg(you, 'That stuff you used to eat is completely disgusting.  Going hungry is nowhere near as painful as having to suffer even the slightest taste of that slop!', MsgType.bad, ctx)
  elseif _sw >= 4 then
    U.set_mutation(you, 'VANITY')
    U.msg(you, 'It\'s so much easier to recognize how you are just that much more attractive than everyone else.  You need to make sure they know it.', MsgType.bad, ctx)
  elseif _sw >= 3 then
    U.set_mutation(you, 'NYCTOPHOBIA')
    U.msg(you, 'There\'s no way you could possibly even contemplate even moving an inch into the darkness because that\'s so so so so so so so incredibly uncomfortably terrifyingly horrible.  Please no.', MsgType.bad, ctx)
  elseif _sw >= 2 then
    U.set_mutation(you, 'PACIFIST')
    U.unset_mutation(you, 'PSYCHOPATH')
    U.unset_mutation(you, 'NUMB')
    U.msg(you, 'You\'ve realized that you\'re far more empathetic to others.  Even those who may not deserve it.', MsgType.bad, ctx)
  elseif _sw >= 1 then
    U.set_mutation(you, 'PSYCHOPATH')
    U.unset_mutation(you, 'PACIFIST')
    U.unset_mutation(you, 'NUMB')
    U.msg(you, 'You suddenly feel much less empathetic towards others.', MsgType.neutral, ctx)
  end
  M['EOC_TELEPATH_MENTAL_ENGINEERING_SIDE_EFFECTS'](you, npc, ctx)
  return true
end
