M['EOC_TELEPATH_MESMERIZE_2'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATH_MESMERIZE_2'](you, npc, ctx) then
    if (U.x_in_y(1, 2) and (U.badcond('EOC_TELEPATH_MESMERIZE_2', 'u_has_species') or U.badcond('EOC_TELEPATH_MESMERIZE_2', 'u_has_species') or U.badcond('EOC_TELEPATH_MESMERIZE_2', 'u_has_species'))) then
      U.add_effect(you, 'psi_stunned', TimeDuration.from_turns(U.round(V.uget(you, 'telepath_mesmerism_duration'))), nil, nil)
      U.add_effect(you, 'effect_telepath_mesmerize_tracker', TimeDuration.from_turns(U.round(V.uget(you, 'telepath_mesmerism_duration'))), nil, nil)
      U.msg(npc, 'You mesmerize the alien creature and it stands in a daze.', MsgType.good, ctx)
    else
      U.msg(npc, 'Your target resists the mesmerism!', MsgType.bad, ctx)
    end
    if (U.x_in_y(19, 20) and U.badcond('EOC_TELEPATH_MESMERIZE_2', 'u_has_species')) then
      U.add_effect(you, 'psi_stunned', TimeDuration.from_turns(U.round(V.uget(you, 'telepath_mesmerism_duration'))), nil, nil)
      U.add_effect(you, 'effect_telepath_mesmerize_tracker', TimeDuration.from_turns(U.round(V.uget(you, 'telepath_mesmerism_duration'))), nil, nil)
      U.msg(npc, 'You mesmerize the feral human and they stand in a daze.', MsgType.good, ctx)
    else
      U.msg(npc, 'Your target resists the mesmerism!', MsgType.bad, ctx)
    end
    if ((not U.badcond('EOC_TELEPATH_MESMERIZE_2', 'u_has_species')) and (not U.badcond('EOC_TELEPATH_MESMERIZE_2', 'u_has_species')) and (not U.badcond('EOC_TELEPATH_MESMERIZE_2', 'u_has_species')) and (not U.badcond('EOC_TELEPATH_MESMERIZE_2', 'u_has_species'))) then
      U.add_effect(you, 'psi_stunned', TimeDuration.from_turns(U.round(V.uget(you, 'telepath_mesmerism_duration'))), nil, nil)
      U.add_effect(you, 'effect_telepath_mesmerize_tracker', TimeDuration.from_turns(U.round(V.uget(you, 'telepath_mesmerism_duration'))), nil, nil)
      U.msg(npc, 'You mesmerize your target and they stand in a daze.', MsgType.good, ctx)
    end
    return false
  end
  if (not U.x_in_y(((math.min((m.int(you) + m.per(you)), 30) + (U.rng(0, 9) + 1)) + (U.rng(0, 9) + 1)), 40)) then
    U.add_effect(you, 'psi_stunned', TimeDuration.from_turns(U.round(V.uget(you, 'telepath_mesmerism_duration'))), nil, nil)
    U.add_effect(you, 'effect_telepath_mesmerize_tracker', TimeDuration.from_turns(U.round(V.uget(you, 'telepath_mesmerism_duration'))), nil, nil)
    U.msg(npc, 'You mesmerize your target and they stand in a daze.', MsgType.good, ctx)
  else
    U.msg(npc, 'Your target resists the mesmerism!', MsgType.bad, ctx)
  end
  return true
end
C['EOC_TELEPATH_MORALE_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  return you:has_effect(U.eid('effect_telepathic_morale'))
end
M['EOC_TELEPATH_MORALE_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPATH_MORALE_DRAIN'](you, npc, ctx) then
    return false
  end
  if (m.spell_level(you, 'telepathic_morale') >= 1) then
    V.uset(you, 'latest_channeled_power_difficulty', U.spell_difficulty('telepathic_morale'))
  else
    V.uset(you, 'latest_channeled_power_difficulty', U.spell_difficulty('telepathic_morale_knack'))
  end
  M['EOC_PSIONICS_GAIN_NETHER_ATTUNEMENT_2'](you, npc, ctx)
  M['EOC_PSI_MAINTENANCE_CALORIE_COST_CALCULATOR'](you, npc, ctx)
  if (m.spell_level(you, 'telepathic_morale') >= 1) then
    m.gain_spell_exp(you, 'telepathic_morale', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  else
    m.gain_spell_exp(you, 'telepathic_morale_knack', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  end
  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  U.add_morale(you, 'morale_telepathy', U.round(((((m.spell_level(you, 'telepathic_morale') + m.spell_level(you, 'telepathic_morale_knack')) * 1) + 10) * J.psionic_power_modifiers(you, npc, ctx))), U.round(35), TimeDuration.from_turns(U.round(U.rng(((((m.spell_level(you, 'telepathic_morale') + m.spell_level(you, 'telepathic_morale_knack')) * 381) + 981) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'telepathic_morale') * 899) + 2520) * J.psionic_power_modifiers(you, npc, ctx))))), TimeDuration.from_turns(U.round((U.rng(((((m.spell_level(you, 'telepathic_morale') + m.spell_level(you, 'telepathic_morale_knack')) * 381) + 981) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'telepathic_morale') * 899) + 2520) * J.psionic_power_modifiers(you, npc, ctx))) / 2))))
  util.queue_eoc(function(y) M['EOC_TELEPATH_MORALE_DRAIN'](y, npc, ctx) end, you, U.rng(((((m.spell_level(you, 'telepathic_morale') + m.spell_level(you, 'telepathic_morale_knack')) * 381) + 981) * J.psionic_power_modifiers(you, npc, ctx)), ((((m.spell_level(you, 'telepathic_morale') + m.spell_level(you, 'telepathic_morale_knack')) * 899) + 2520) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
