  V.uset(you, 'nether_attunement_telepathy_scaling', V.uget(npc, 'nether_attunement_power_scaling'))
  V.uset(you, 'mood_stabilized_power_level', ((V.uget(you, 'telepathy_power_level') * V.uget(you, 'telepathy_intelligence')) * V.uget(you, 'nether_attunement_telepathy_scaling')))
