  U.msg(you, 'You attempt to teleport to your destination, but your skin merely tingles and nothing happens.  You\'re carrying too much.', MsgType.bad, ctx)
  return true
end
C['EOC_TELEPORTER_OUBLIETTE_HANDLING'] = function(you, npc, ctx)
  ctx = ctx or {}
  return ((not U.has_creature_flag(you, 'TELESTOP')) and (not U.has_creature_flag(you, 'TELEPORT_IMMUNE')) and (not U.has_item_flag(you, 'DIMENSIONAL_ANCHOR')))
end
M['EOC_TELEPORTER_OUBLIETTE_HANDLING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPORTER_OUBLIETTE_HANDLING'](you, npc, ctx) then
    U.msg(npc, 'Your target wavers for a moment, but nothing happens.', MsgType.neutral, ctx)
    return false
  end
  M['EOC_TELEPORTER_OUBLIETTE_HANDLING_2'](you, npc, ctx)
  return true
end
C['EOC_TELEPORTER_OUBLIETTE_HANDLING_2'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (not (not U.is_avatar(you)))
end
M['EOC_TELEPORTER_OUBLIETTE_HANDLING_2'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPORTER_OUBLIETTE_HANDLING_2'](you, npc, ctx) then
    V.uset(you, 'psi_teleporter_damage', U.rng((((15 + (m.spell_level(npc, 'teleport_banish') * 15)) * ((m.int(npc) + 10) / 20)) * V.uget(npc, 'nether_attunement_power_scaling')), (((350 + (m.spell_level(npc, 'teleport_banish') * 35)) * ((m.int(npc) + 10) / 20)) * V.uget(npc, 'nether_attunement_power_scaling'))))
    V.uset(you, 'health_comparison', ((((((U.hp(you, 'arm_l') + U.hp(you, 'arm_r')) + U.hp(you, 'leg_l')) + U.hp(you, 'leg_r')) + U.hp(you, 'torso')) + U.hp(you, 'head')) / 3))
    if (V.uget(you, 'psi_teleporter_damage') > V.uget(you, 'health_comparison')) then
      U.msg(npc, 'With a tremendous mental exertion, you hurl your target…elsewhere.', MsgType.neutral, ctx)
      U.die(you)
    end
    return false
  end
  V.uset(you, 'psi_teleporter_damage', U.rng((((15 + (m.spell_level(npc, 'teleport_banish') * 15)) * ((m.int(npc) + 10) / 20)) * V.uget(npc, 'nether_attunement_power_scaling')), (((350 + (m.spell_level(npc, 'teleport_banish') * 35)) * ((m.int(npc) + 10) / 20)) * V.uget(npc, 'nether_attunement_power_scaling'))))
  V.uset(you, 'health_comparison', U.hp(you, 'ALL'))
  if (V.uget(you, 'psi_teleporter_damage') > V.uget(you, 'health_comparison')) then
    U.die(you)
    U.msg(npc, 'With a tremendous mental exertion, you hurl your target…elsewhere.', MsgType.neutral, ctx)
  end
  return true
end
C['EOC_TELEPORTER_THE_HOUNDS_FOLLOW'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (you:has_trait(U.mid('TELEPORTER')) and (('teleport_blink' == tostring(ctx['spell'] or '')) or ('teleport_phase' == tostring(ctx['spell'] or '')) or ('teleport_transpose' == tostring(ctx['spell'] or '')) or ('teleport_farstep' == tostring(ctx['spell'] or ''))) and (U.monsters_nearby(you, 'mon_hound_tindalos', 50) > 0) and (not U.has_creature_flag(you, 'TEEPSHIELD')))
end
M['EOC_TELEPORTER_THE_HOUNDS_FOLLOW'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPORTER_THE_HOUNDS_FOLLOW'](you, npc, ctx) then
    return false
  end
  U.msg(you, 'As you come out of the darkness and the cold of the teleport, you feel the prickling sensation of watching eyes and see wisps of swirling fog in the corners of your vision.  They\'re still on your trail.', MsgType.bad, ctx)
  U.add_effect(you, 'tindrift', TimeDuration.from_days(1), nil, nil)
  return true
end
