C['EOC_TELEPORT_BLINK_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return ((not U.has_item_flag(you, 'DIMENSIONAL_ANCHOR')) and (not U.has_creature_flag(you, 'DIMENSIONAL_ANCHOR')) and (not U.has_creature_flag(you, 'TELEPORT_LOCK')))
end
M['EOC_TELEPORT_BLINK_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPORT_BLINK_INITIATE'](you, npc, ctx) then
    U.msg(you, 'You feel a strange, inward force.', MsgType.bad, ctx)
    return false
  end
  M['EOC_TELEPORT_SELF_CARRIED_VOLUME_CHECKER'](you, npc, ctx)
  ctx['teleport_blink_limit'] = (((m.spell_level(you, 'teleport_blink') * 3500) + 5000) * J.psionic_power_modifiers(you, npc, ctx))
  U.msg(you, 'Your Blink volume limit is <context_val:teleport_blink_limit>.', MsgType.debug, ctx)
  if (V.uget(you, 'teleport_total_carried_volume') <= (ctx['teleport_blink_limit'] or 0)) then
    U.cast_spell(you, 'teleport_blink_real', m.spell_level(you, 'teleport_blink'), nil)
    U.msg(you, 'You vanish and reappear nearby.', MsgType.neutral, ctx)
  else
    U.msg(you, 'You attempt to teleport to somewhere nearby, but your skin merely tingles and nothing happens.  You\'re carrying too much.', MsgType.bad, ctx)
  end
  return true
end
