  if not C['EOC_TELEPORT_FARSTEP_INITIATE'](you, npc, ctx) then
    U.msg(you, 'You feel a strange, inward force.', MsgType.bad, ctx)
    return false
  end
  M['EOC_TELEPORT_SELF_CARRIED_VOLUME_CHECKER'](you, npc, ctx)
  ctx['teleport_farstep_limit'] = (((m.spell_level(you, 'teleport_farstep') * 5000) + 8000) * J.psionic_power_modifiers(you, npc, ctx))
  U.msg(you, 'Your Farstep volume limit is <context_val:teleport_farstep_limit>.', MsgType.debug, ctx)
  if (V.uget(you, 'teleport_total_carried_volume') <= (ctx['teleport_farstep_limit'] or 0)) then
    U.cast_spell_targeted(you, 'teleport_farstep_real', nil, math.min((((m.spell_level(you, 'teleport_farstep') * 2) + 1) * J.psionic_power_modifiers(you, npc, ctx)), 80), '[Ψ]Farstep: choose target.')
    U.msg(you, 'There is a moment of darkness and terrible cold, and you are somewhere else.', MsgType.neutral, ctx)
  else
    M['EOC_TELEPORTER_GATEWAY_MESSAGE_CARRYING_TOO_MUCH'](you, npc, ctx)
  end
  return true
end
