M['EOC_TELEPORT_GATEWAY_ATTUNE_01'] = function(you, npc, ctx)
  ctx = ctx or {}
  M['EOC_TELEPORTER_ATTUNING_MESSAGE'](you, npc, ctx)
  U.add_effect(you, 'effect_teleporter_attuning_to_area', TimeDuration.from_hours(8), nil, nil)
  U.assign_activity(you, 'ACT_PSI_TELEPORTER_ATTUNING', 28800)
  util.queue_eoc(function(y) M['EOC_TELEPORT_GATEWAY_ATTUNE_01_SUCCESS'](y, npc, ctx) end, you, (28800 - U.clamp((m.spell_level(you, 'teleport_gateway') * 1200), 0, 27000)))
  return true
end
