C['EOC_TELEPORT_ITEM_APPORT'] = function(you, npc, ctx)
  ctx = ctx or {}
  return true
end
M['EOC_TELEPORT_ITEM_APPORT'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.run_inv_eocs(you, ctx, 'all', {wielded_only = true, cond = function(_it) return (U.item_volume(_it) > 0) end}, function(_it)
    U.run_inv_eocs(you, ctx, 'all', {wielded_only = true, cond = function(_it) return ((U.item_volume(_it) <= (((m.spell_level(you, 'teleport_item_apport') * 2500) + 2000) * J.psionic_power_modifiers(you, npc, ctx))) and (U.item_volume(_it) > 0)) end}, function(_it)
      ctx['teleporter_item_apport_location'] = U.query_tile(you, {range = math.min((((m.spell_level(you, 'teleport_item_apport') * 1.25) + 2) * J.psionic_power_modifiers(you, npc, ctx)), 80), msg = 'Select apport location.'})
      if not ctx['teleporter_item_apport_location'] then return false end
      if U.truthy(U.b2n(ctx['teleporter_item_apport_location'] ~= nil)) then
        if (U.badcond('EOC_TELEPORT_ITEM_APPORT', 'map_terrain_with_flag') or U.badcond('EOC_TELEPORT_ITEM_APPORT', 'map_terrain_with_flag')) then
          U.msg(you, 'You cannot apport an item inside a solid object.', MsgType.bad, ctx)
        else
          U.teleport_to_pos(npc, ctx['teleporter_item_apport_location'])
          U.msg(you, 'The item in your hands grows freezing cold for a moment before vanishing.', MsgType.neutral, ctx)
        end
      else
        U.msg(you, 'Canceled', MsgType.neutral, ctx)
      end
    end)
  end)
  return true
end
