C['EOC_TELEPORT_LOCI_ESTABLISHMENT_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  return you:has_effect(U.eid('effect_teleport_loci_establishment'))
end
M['EOC_TELEPORT_LOCI_ESTABLISHMENT_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPORT_LOCI_ESTABLISHMENT_DRAIN'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'latest_channeled_power_difficulty', 6)
  M['EOC_PSIONICS_GAIN_NETHER_ATTUNEMENT_2'](you, npc, ctx)
  M['EOC_PSI_MAINTENANCE_CALORIE_COST_CALCULATOR'](you, npc, ctx)
  m.gain_spell_exp(you, 'teleport_loci_establishment', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_TELEPORT_LOCI_ESTABLISHMENT_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'teleport_loci_establishment') * 2) + 20) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'teleport_loci_establishment') * 4) + 200) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
C['EOC_TELEPORT_LOCI_ESTABLISHMENT_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (not you:has_effect(U.eid('effect_teleport_loci_establishment')))
end
M['EOC_TELEPORT_LOCI_ESTABLISHMENT_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPORT_LOCI_ESTABLISHMENT_INITIATE'](you, npc, ctx) then
    M['EOC_TELEPORT_REMOVE_LOCI_ESTABLISHMENT'](you, npc, ctx)
    return false
  end
  U.msg(you, 'You\'ve established a locus to return to later.', MsgType.good, ctx)
  M['EOC_POWER_MAINTENANCE_PLUS_ONE'](you, npc, ctx)
  ctx['teleporter_loci_establishment_loc'] = you:get_pos_ms()
  U.save_location(you, 'teleporter_loci_establishment_loc', ctx['teleporter_loci_establishment_loc'])
  U.add_effect(you, 'effect_teleport_loci_establishment', 'PERMANENT', nil, nil)
  util.queue_eoc(function(y) M['EOC_TELEPORT_LOCI_ESTABLISHMENT_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'teleport_loci_establishment') * 1) + 20) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'teleport_loci_establishment') * 4) + 200) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
C['EOC_TELEPORT_LOCI_TECHNIQUE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return you:has_effect(U.eid('effect_teleport_loci_establishment'))
end
M['EOC_TELEPORT_LOCI_TECHNIQUE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPORT_LOCI_TECHNIQUE'](you, npc, ctx) then
    U.msg(you, 'You are currently not concentrating on [Ψ]Loci Establishment!', MsgType.neutral, ctx)
    return false
  end
  if ((not U.has_item_flag(you, 'DIMENSIONAL_ANCHOR')) and (not U.has_creature_flag(you, 'DIMENSIONAL_ANCHOR')) and (not U.has_creature_flag(you, 'TELEPORT_LOCK'))) then
    M['EOC_TELEPORT_SELF_CARRIED_VOLUME_CHECKER'](you, npc, ctx)
    ctx['teleport_loci_technique_limit'] = (((m.spell_level(you, 'teleport_loci_technique') * 5000) + 8000) * J.psionic_power_modifiers(you, npc, ctx))
    U.msg(you, 'Your Loci Technique volume limit is <context_val:teleport_loci_technique_limit>.', MsgType.debug, ctx)
    if (V.uget(you, 'teleport_total_carried_volume') <= (ctx['teleport_loci_technique_limit'] or 0)) then
      if U.teleport_to_saved(you, you, 'teleporter_loci_establishment_loc') then
        U.msg(you, 'You feel a moment of darkness and terrible cold, but you are quickly back at your established locus.', MsgType.good, ctx)
      else
        U.msg(you, 'Something goes wrong with the Loci Technique!', MsgType.bad, ctx)
      end
    else
      M['EOC_TELEPORTER_GATEWAY_MESSAGE_CARRYING_TOO_MUCH'](you, npc, ctx)
    end
  else
    U.msg(you, 'You feel a strange, inward force.', MsgType.bad, ctx)
  end
  return true
end
C['EOC_TELEPORT_MATRIX_AWAKENING'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (you:has_trait(U.mid('TELEPORTER')) or you:has_trait(U.mid('CANNOT_GAIN_PSIONICS')))
end
M['EOC_TELEPORT_MATRIX_AWAKENING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPORT_MATRIX_AWAKENING'](you, npc, ctx) then
    V.uset(you, 'awakening_reducer', J.matrix_awakening_odds(you, npc, ctx, V.uget(you, 'awakening_countup')))
    M['EOC_TELEPORT_MATRIX_AWAKENING_2'](you, npc, ctx)
    return false
  end
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  It starts pulsing, first slowly and more rapidly, and your head starts pounding in time with the light.  You tear your gaze away but the pounding in your head remains.', MsgType.neutral, ctx)
  U.add_effect(you, 'psionic_overload', TimeDuration.from_hours(1), nil, nil)
  U.add_effect(you, 'stunned', TimeDuration.from_turns(10), nil, nil)
  return true
end
