  ctx = ctx or {}
  if not C['EOC_TELEPORT_MATRIX_AWAKENING_2'](you, npc, ctx) then
    M['EOC_TELEPORT_MATRIX_AWAKENING_FAILURE'](you, npc, ctx)
    return false
  end
  M['EOC_TELEPORT_MATRIX_AWAKENING_SUCCESS'](you, npc, ctx)
