  ctx = ctx or {}
  return true
end
M['EOC_TELEPORT_MATRIX_AWAKENING_FAILURE'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  As the light spreads and illuminates the surrounding terrain, the air shimmers slightly.  Images appear, locations and times, all overlapping in a kaleidoscope of color and sound that makes your head throb.  You tear your gaze away from the now-dark crystal but the pounding in your head remains.', MsgType.neutral, ctx)
  U.add_effect(you, 'psionic_overload', TimeDuration.from_hours(1), nil, nil)
  U.add_effect(you, 'stunned', TimeDuration.from_turns(10), nil, nil)
  util.queue_eoc(function(y) M['EOC_TELEPORT_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  return true
end
C['EOC_TELEPORT_MATRIX_AWAKENING_SUCCESS'] = function(you, npc, ctx)
  ctx = ctx or {}
  return true
end
M['EOC_TELEPORT_MATRIX_AWAKENING_SUCCESS'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  As the light spreads and illuminates the surrounding terrain, the air shimmers slightly.  You can see your bedroom, in the place you\'ve been holed up after the end of the world; you can see a city, with buildings made of greenish soapstone and people whose bodies and faces are merely indistinct shadows; you can see the cafe you always used to hang out in, empty and ruined, with the door in back thumping rhythmically as something pounds on it; you can see a point of light, floating in the midst of a starry void, and hear a reedy toneless hum.  You see the paths that link all four of these places and an infinite number of others, glowing paths that you could easy follow in directions you had never previously known existed.  The light in the crystal fades as you set one foot on a path.', MsgType.neutral, ctx)
  M['EOC_PSI_AWAKENING_TELEPORTATION_FINALIZATION'](you, npc, ctx)
  U.cast_spell(you, 'teleport_blink_monster', nil, nil)
  U.msg(you, 'Reality suddenly warps around you and you are somewhere else!', MsgType.neutral, ctx)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  util.queue_eoc(function(y) M['EOC_TELEPORT_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
  return true
end
