C['EOC_TELEPORT_OUBLIETTE_MONSTER'] = function(you, npc, ctx)
  ctx = ctx or {}
  return (not (U.has_creature_flag(you, 'TELESTOP') or U.has_creature_flag(you, 'TELEPORT_IMMUNE') or U.has_creature_flag(you, 'TELEPORT_LOCK') or U.has_item_flag(you, 'DIMENSIONAL_ANCHOR')))
end
M['EOC_TELEPORT_OUBLIETTE_MONSTER'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPORT_OUBLIETTE_MONSTER'](you, npc, ctx) then
    U.msg(you, 'You feel a strange, inward force.', MsgType.neutral, ctx)
    return false
  end
  ctx['damage_done'] = (50 + U.rng(0, 100))
  if (true and ((ctx['damage_done'] or 0) >= ((((((U.hp(you, 'arm_l') + U.hp(you, 'arm_r')) + U.hp(you, 'leg_l')) + U.hp(you, 'leg_r')) + U.hp(you, 'torso')) + U.hp(you, 'head')) / 3))) then
    if U.is_avatar(you) then
      M['EOC_MOM_OUBLIETTE_MONSTER_PICK_DIMENSION'](you, npc, ctx)
    else
      U.die(you)
    end
  end
  if (U.badcond('EOC_TELEPORT_OUBLIETTE_MONSTER', 'u_is_monster') and ((ctx['damage_done'] or 0) >= U.hp(you, 'ALL'))) then
    U.die(you)
  end
  return true
end
C['EOC_TELEPORT_PHASE_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  return ((not U.has_item_flag(you, 'DIMENSIONAL_ANCHOR')) and (not U.has_creature_flag(you, 'DIMENSIONAL_ANCHOR')) and (not U.has_creature_flag(you, 'TELEPORT_LOCK')))
end
M['EOC_TELEPORT_PHASE_INITIATE'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_TELEPORT_PHASE_INITIATE'](you, npc, ctx) then
    U.msg(you, 'You feel a strange, inward force.', MsgType.bad, ctx)
    return false
  end
  M['EOC_TELEPORT_SELF_CARRIED_VOLUME_CHECKER'](you, npc, ctx)
  ctx['teleport_phase_limit'] = (((m.spell_level(you, 'teleport_phase') * 5000) + 10000) * J.psionic_power_modifiers(you, npc, ctx))
  U.msg(you, 'Your Phase volume limit is <context_val:teleport_phase_limit>.', MsgType.debug, ctx)
  if (V.uget(you, 'teleport_total_carried_volume') <= (ctx['teleport_phase_limit'] or 0)) then
    U.cast_spell_targeted(you, 'teleport_phase_real', m.spell_level(you, 'teleport_phase'), U.clamp((((m.spell_level(you, 'teleport_phase') * 0.1) + 2) * J.psionic_power_modifiers(you, npc, ctx)), 2, 4), '[Ψ]Phase: choose target.')
    U.msg(you, 'There is a brief moment of darkness and terrible cold, and you are somewhere else.', MsgType.neutral, ctx)
  else
    U.msg(you, 'You attempt to phase through the barrier, but your skin merely tingles and nothing happens.  You\'re carrying too much.', MsgType.bad, ctx)
  end
  return true
end
