M['EOC_VITAKINETIC_AWAKENING_KNACK_HANDLING'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_VITAKINETIC_AWAKENING_KNACK_HANDLING'](you, npc, ctx) then
    return false
  end
  if (m.spell_level(you, 'vita_health_power_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'vita_health_power_knack')
    U.set_spell_level(you, 'vita_health_power', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'vita_health_power_knack', -(1))
  end
  if (m.spell_level(you, 'vita_concentrated_healing_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'vita_concentrated_healing_knack')
    U.set_spell_level(you, 'vita_concentrated_healing', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'vita_concentrated_healing_knack', -(1))
  end
  if (m.spell_level(you, 'vita_remove_poison_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'vita_remove_poison_knack')
    U.set_spell_level(you, 'vita_remove_poison', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'vita_remove_poison_knack', -(1))
  end
  if (m.spell_level(you, 'vita_cure_disease_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'vita_cure_disease_knack')
    U.set_spell_level(you, 'vita_cure_disease', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'vita_cure_disease_knack', -(1))
  end
  if (m.spell_level(you, 'vita_banish_illness_knack') > 0) then
    ctx['temp_var'] = m.spell_level(you, 'vita_banish_illness_knack')
    U.set_spell_level(you, 'vita_banish_illness', (ctx['temp_var'] or 0))
    U.set_spell_level(you, 'vita_banish_illness_knack', -(1))
  end
  if (U.spell_count(you, nil) == 0) then
    U.unset_mutation(you, 'PSYCHIC_KNACK')
  end
  return true
end
