M['EOC_VITAKIN_BANISH_ILLNESS_SELECTOR'] = function(you, npc, ctx)
  ctx = ctx or {}
  local _pick = U.select_eoc_menu('', {'EOC_VITAKIN_BANISH_ILLNESS_MINOR', 'EOC_VITAKIN_BANISH_ILLNESS_ASTHMA', 'EOC_VITAKIN_BANISH_ILLNESS_CHEMIMBALANCE', 'EOC_VITAKIN_BANISH_ILLNESS_SCHIZOPHRENIC', 'EOC_VITAKIN_BANISH_ILLNESS_JITTERY', 'EOC_VITAKIN_BANISH_ILLNESS_MOODSWINGS', 'EOC_VITAKIN_BANISH_ILLNESS_WEAKENING', 'EOC_VITAKIN_BANISH_ILLNESS_NARCOLEPTIC', 'EOC_VITAKIN_BANISH_ILLNESS_SEASONAL_ALLERGIES', 'EOC_VITAKIN_BANISH_ILLNESS_SEASONAL_AFFECTIVE', 'EOC_VITAKIN_BANISH_ILLNESS_XE_VAMPIRISM', 'EOC_NONE'}, {'Purge Minor Ailments', 'Purge Asthma', 'Purge Chemical Imbalance', 'Purge Kaluptic Psychosis', 'Purge Jitters', 'Purge Mood Swings', 'Purge Wasting Sickness', 'Purge Narcolepsy', 'Purge Seasonal Allergies', 'Purge Seasonal Affective Disorder', 'Purge Strange Blood Disorder', 'Nevermind'}, {'Attempt to cure your minor illnesses.', 'Attempt to cure your asthma.', 'Attempt to cure your chemical imbalance.', 'Attempt to cure your kaluptic psychosis.', 'Attempt to cure your jitters.', 'Attempt to cure your mood swings.', 'Attempt to cure your weakening sickness.', 'Attempt to cure your narcolepsy.  This meditation is extremely intensive, and is correspondingly more draining.', 'Attempt to cure your seasonal allergies.', 'Attempt to cure your seasonal affective disorder.', 'Attempt to cure your strange blood disorder.', 'Do nothing for now.'}, you, npc, ctx, true)
  if not _pick then return false end
  M[_pick](you, npc, ctx)
  return true
end
