  ctx = ctx or {}
  if not C['EOC_VITAKIN_CONCENTRATED_HEALING_DERMATIK_CHECK_2'](you, npc, ctx) then
    util.queue_eoc(function(y) M['EOC_VITAKIN_CONCENTRATED_HEALING_DERMATIK_CHECK'](y, npc, ctx) end, you, U.rng((3600 - ((m.spell_level(you, 'vita_concentrated_healing') * 60) * J.psionic_power_modifiers(you, npc, ctx))), (3600 - ((m.spell_level(you, 'vita_concentrated_healing') * 60) * J.psionic_power_modifiers(you, npc, ctx)))))
    return false
