M['EOC_VITAKIN_MATRIX_AWAKENING_FAILURE'] = function(you, npc, ctx)
  ctx = ctx or {}
  U.msg(you, 'You gaze into the strange crystal and the light slowly grows brighter.  In the light, you can see yourself, standing there holding a glowing crystal, and then there\'s a flare of light and you close your eyes against its intensity.  Your head pounds, and when you manage to open your eyes again, the crystal is dark.', MsgType.neutral, ctx)
  U.add_effect(you, 'psionic_overload', TimeDuration.from_hours(1), nil, nil)
  U.add_effect(you, 'stunned', TimeDuration.from_turns(10), nil, nil)
  util.queue_eoc(function(y) M['EOC_VITAKIN_CRYSTAL_DRAINING'](y, npc, ctx) end, you, 1)
  U.assign_activity(you, 'ACT_CRYSTAL_AWAKENING_MEDITATION', 5)
  return true
end
