M['EOC_VITAKIN_NO_NEED_FOR_SLEEP'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_VITAKIN_NO_NEED_FOR_SLEEP'](you, npc, ctx) then
    M['EOC_VITAKIN_REMOVE_NO_NEED_FOR_SLEEP'](you, npc, ctx)
    return false
  end
  U.msg(you, 'You blink suddenly.', MsgType.good, ctx)
  U.add_effect(you, 'effect_vitakin_no_need_for_sleep', 'PERMANENT', nil, nil)
  M['EOC_POWER_MAINTENANCE_PLUS_ONE'](you, npc, ctx)
  M['EOC_TELEPATH_REMOVE_TELEPATHIC_CONCENTRATION'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_VITAKIN_NO_NEED_FOR_SLEEP_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'vita_no_need_for_sleep') * 210) + 1950) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'vita_no_need_for_sleep') * 590) + 4180) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
C['EOC_VITAKIN_NO_NEED_FOR_SLEEP_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  return you:has_effect(U.eid('effect_vitakin_no_need_for_sleep'))
end
M['EOC_VITAKIN_NO_NEED_FOR_SLEEP_DRAIN'] = function(you, npc, ctx)
  ctx = ctx or {}
  if not C['EOC_VITAKIN_NO_NEED_FOR_SLEEP_DRAIN'](you, npc, ctx) then
    return false
  end
  V.uset(you, 'latest_channeled_power_difficulty', 7)
  M['EOC_PSIONICS_GAIN_NETHER_ATTUNEMENT_2'](you, npc, ctx)
  M['EOC_PSI_MAINTENANCE_CALORIE_COST_CALCULATOR'](you, npc, ctx)
  m.gain_spell_exp(you, 'vita_no_need_for_sleep', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  if (m.sleep_deprivation(you) >= 250) then
    U.unported('EOC_VITAKIN_NO_NEED_FOR_SLEEP_DRAIN', 'write u_val:sleep_deprivation')
  end
  if (m.sleep_deprivation(you) >= 100) then
    U.unported('EOC_VITAKIN_NO_NEED_FOR_SLEEP_DRAIN', 'write u_val:sleep_deprivation')
  end
  if (m.sleep_deprivation(you) >= 50) then
    U.unported('EOC_VITAKIN_NO_NEED_FOR_SLEEP_DRAIN', 'write u_val:sleep_deprivation')
  end
  util.queue_eoc(function(y) M['EOC_VITAKIN_NO_NEED_FOR_SLEEP_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'vita_no_need_for_sleep') * 210) + 1950) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'vita_no_need_for_sleep') * 590) + 4180) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
