  V.uset(you, 'vitakin_return_from_death_kcal', you:get_stored_kcal())
  m.gain_spell_exp(you, 'vita_return_from_death', U.round(J.psionic_power_experience_formula(you, npc, ctx)))
  M['EOC_POWER_MAINTENANCE_CONCENTRATION_CHECK'](you, npc, ctx)
  util.queue_eoc(function(y) M['EOC_VITAKIN_RETURN_FROM_DEATH_DRAIN'](y, npc, ctx) end, you, U.rng((((m.spell_level(you, 'vita_return_from_death') * 962) + 3978) * J.psionic_power_modifiers(you, npc, ctx)), (((m.spell_level(you, 'vita_return_from_death') * 2819) + 12360) * J.psionic_power_modifiers(you, npc, ctx))))
  return true
end
