    local _sw = U.rng(0, 4)
    if _sw >= 4 then
      U.msg(you, 'You draw the plus symbol card, look at it for a moment, and put it back in the deck.', MsgType.neutral, ctx)
    elseif _sw >= 3 then
      U.msg(you, 'You draw the five-pointed star card, look at it for a moment, and put it back in the deck.', MsgType.neutral, ctx)
    elseif _sw >= 2 then
      U.msg(you, 'You draw the hollow square card, look at it for a moment, and put it back in the deck.', MsgType.neutral, ctx)
    elseif _sw >= 1 then
      U.msg(you, 'You draw the three wavy lines card, look at it for a moment, and put it back in the deck.', MsgType.neutral, ctx)
    elseif _sw >= 0 then
      U.msg(you, 'You draw the hollow circle card, look at it for a moment, and put it back in the deck.', MsgType.neutral, ctx)
    end
    return false
  end
  local _sw = U.rng(0, 4)
  if _sw >= 4 then
    U.msg(you, 'You draw the plus symbol card, just as you knew you would.  You look at it for a moment and put it back in the deck.', MsgType.neutral, ctx)
  elseif _sw >= 3 then
    U.msg(you, 'You draw the five-pointed star card, just as you knew you would.  You look at it for a moment and put it back in the deck.', MsgType.neutral, ctx)
  elseif _sw >= 2 then
    U.msg(you, 'You draw the hollow square card, just as you knew you would.  You look at it for a moment and put it back in the deck.', MsgType.neutral, ctx)
  elseif _sw >= 1 then
    U.msg(you, 'You draw the three wavy lines card, just as you knew you would.  You look at it for a moment and put it back in the deck.', MsgType.neutral, ctx)
  elseif _sw >= 0 then
    U.msg(you, 'You draw the hollow circle card, just as you knew you would.  You look at it for a moment and put it back in the deck.', MsgType.neutral, ctx)
  end
  return true
end
